'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stageNames={import:'导入',dedup:'查重',roles:'任职',internal:'内部',team:'团体',couple:'情侣',normal:'普通',overview:'总览',export:'导出'};
let S=V.blank(),page='import',selected=new Set(),focusId=null,filter='',query='',pageSize=4,pageNo=1,listView=false,currentTeam='',undoStack=[],redoStack=[],dirty=false,db=null,history=[],busy=false,toastTimer,lastSelected=null;
let pendingImports=[],exportCols=[],exportSelection=[],exportMode='book',exportSpecial='',exportInitialized=false;
let issuePeople=new Set(),allocationSpeed='normal',animationPaused=false,animationSkip=false;
const colors=['#8d6ac8','#279f97','#ce8750','#5c83cd','#be6592','#819a4b'];
const groupOf=id=>S.groups.find(g=>g.id===id),personOf=id=>S.people.find(p=>p.id===id),leader=p=>S.groups.some(g=>g.leader===p.id),personLocation=p=>p.independent?'independent':p.group||(p.reserve?'reserve':'pending');
const allTeams=()=>[...new Set(S.people.flatMap(p=>p.teams))].sort((a,b)=>a.localeCompare(b,'zh-CN'));
function toast(text){const success=/^(已保存$|已保存阶段快照|已删除项目|已分配 |已应用导入修改|已导入 |已保留所选来源|已标记为不同的人|已撤销$|已重做$|已交换$|活动名称已保存|分配完成|Excel 已生成|草稿已生成|备份已下载|已恢复|项目已恢复|已清空|新活动已创建|模板已下载|样例包含)/.test(text);if(success)globalThis.ButtonFeedback?.success();$('toast').classList.toggle('toast-success',success);$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200)}
function modal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
function closeModal(){$('modal').close()}
function errorBox(error){globalThis.ButtonFeedback?.fail();modal('请先处理',`<div class="notice">${esc(error.message||error).replace(/\n/g,'<br>')}</div><button onclick="closeModal()">知道了</button>`)}
function download(name,data,type='application/octet-stream'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
const safeName=s=>String(s).replace(/[\\/:*?"<>|\r\n]/g,'_').slice(0,70)||'名单';
function now(){return new Date().toLocaleString('zh-CN',{hour12:false})}
function promiseRequest(req){return new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('volunteer-full-v1',1);req.onupgradeneeded=()=>{req.result.createObjectStore('snapshots',{keyPath:'id'});req.result.createObjectStore('meta')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(Error('本地存储被其他窗口占用'))})}
async function saveSnapshot(label,state=S,imports=pendingImports){if(!db){toast('本地存储不可用，请下载项目备份');return false}try{const snapshot={id:V.uid(),time:now(),created:Date.now(),label,state:V.copy(state),pendingImports:V.copy(imports)};await new Promise((resolve,reject)=>{const tx=db.transaction(['snapshots','meta'],'readwrite');tx.objectStore('snapshots').add(snapshot);tx.objectStore('meta').put(snapshot.id,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});history.unshift(snapshot);dirty=false;updateSaved('已保存 '+snapshot.time.split(' ').pop());return true}catch(e){toast('保存失败，请下载备份后重试');return false}}
function updateSaved(t){$('saveState').textContent=t}
function backup(){download(safeName(S.name)+'-项目备份.json',JSON.stringify({format:'volunteer-project',version:1,state:S,pendingImports,snapshots:history},null,2),'application/json');toast('备份已下载，包含当前状态与历史版本')}
function checkpoint(){undoStack.push({state:V.copy(S),imports:V.copy(pendingImports)});if(undoStack.length>40)undoStack.shift();redoStack=[]}
function changed(){S.revision++;dirty=true;updateSaved('有未保存的修改')}
function clearConfirmations(){S.confirmed={};S.teamDone=[];S.people.forEach(p=>{p.locked=false});}
function mutate(fn,invalidate=false){if(busy)return;const old=V.copy(S);try{fn();if(invalidate)clearConfirmations();const next=V.copy(S);S=old;checkpoint();S=next;changed();render();return true}catch(e){S=old;errorBox(e);return false}}
function undo(){if(busy)return;if(!undoStack.length)return;redoStack.push({state:V.copy(S),imports:V.copy(pendingImports)});const entry=undoStack.pop();S=entry.state;pendingImports=entry.imports;recoverExport();selected.clear();changed();render();toast('已撤销')}
function redo(){if(busy)return;if(!redoStack.length)return;undoStack.push({state:V.copy(S),imports:V.copy(pendingImports)});const entry=redoStack.pop();S=entry.state;pendingImports=entry.imports;recoverExport();selected.clear();changed();render();toast('已重做')}
function editActivity(){modal('活动名称',`<form onsubmit="event.preventDefault();setActivity()"><input id="newName" class="wide" maxlength="60" value="${esc(S.name)}" required><div class="form-actions"><button type="button" onclick="closeModal()">取消</button><button class="primary">保存名称</button></div></form>`)}
async function setActivity(){const name=$('newName').value.trim();if(!name)return;mutate(()=>{S.name=name});if(await saveSnapshot('修改活动名称')){closeModal();toast('活动名称已保存')}}
function stageLocked(){return page==='team'?S.teamDone.includes(currentTeam):!!S.confirmed[page]}
function unlockStage(){modal('修改已确认安排',`<p>当前及后续阶段将需要重新确认。原快照保留。</p><button class="primary" onclick="doUnlock()">保存当前状态并解锁</button>`)}
async function doUnlock(){if(!await saveSnapshot('修改前备份'))return;const order=['roles','internal','team','couple','normal'];const i=order.indexOf(page);mutate(()=>{order.slice(Math.max(0,i)).forEach(k=>delete S.confirmed[k]);if(i<=2)S.teamDone=[];const us=V.units(S);us.filter(u=>V.eligible(u,page,currentTeam)).flat().forEach(p=>{if(!leader(p))p.locked=false})});closeModal()}
function navigate(next){if(busy)return;if(!['import','dedup','overview','export'].includes(next)&&!S.confirmed.dedup){toast('请先完成查重与关系确认');return}if(['internal','team','couple','normal'].includes(next)&&!S.confirmed.roles){toast('请先确认组长与区长');return}if(next==='team'&&!S.confirmed.internal)return toast('请先确认内部人员');if(next==='couple'&&(!S.confirmed.internal||allTeams().some(t=>!S.teamDone.includes(t))))return toast('请先确认内部人员及所有团体');if(next==='normal'&&!S.confirmed.couple)return toast('请先确认情侣阶段');page=next;pageNo=1;filter='';query='';selected.clear();focusId=null;if(page==='team'&&!allTeams().includes(currentTeam))currentTeam=allTeams().find(t=>!S.teamDone.includes(t))||allTeams()[0]||'';render()}
function stageMembers(){const ids=new Set(V.units(S).filter(u=>V.eligible(u,page,currentTeam)).flat().map(p=>p.id));return S.people.filter(p=>ids.has(p.id)&&!p.independent)}
async function confirmStage(defer=false){if(busy)return;let next=V.copy(S),label=stageNames[page]+'确认',nextPage=page;try{
 if(page==='import'){if(!next.people.length)throw Error('请先导入人员名单');next.confirmed.import=true;nextPage='dedup'}
 else if(page==='dedup'){if(V.duplicateSets(next).length)throw Error('还有重复记录需要确认');V.resolveFamily(next);const errors=V.relationErrors(next);if(errors.length){if(!defer){modal('暂存关联异常',`<p>有 ${V.issueIds(next).size} 人及其关联成员需要单独处理。暂存后标红，不参与自动分配，可继续安排其他人员。</p><div class="form-actions"><button onclick="closeModal()">返回检查</button><button class="primary" onclick="closeModal();confirmStage(true)">暂存并继续</button></div>`);return}V.deferIssues(next)}else V.refreshDeferred(next);next.confirmed.dedup=true;nextPage='roles'}
 else if(page==='roles'){if(!next.confirmed.dedup)throw Error('请先完成查重');V.placeLeaders(next);next.confirmed.roles=true;nextPage='internal'}
 else if(['internal','team','couple','normal'].includes(page)){const required={internal:'roles',team:'internal',couple:'internal',normal:'couple'}[page];if(!next.confirmed[required])throw Error('请先确认前面的分配阶段');if(page==='couple'&&allTeams().some(t=>!next.teamDone.includes(t)))throw Error('请先确认所有团体');if(page==='normal'&&allTeams().some(t=>!next.teamDone.includes(t)))throw Error('请先确认所有团体');const us=V.units(next).filter(u=>V.eligible(u,page,currentTeam));const unresolved=us.flat().filter(p=>!p.group&&!p.independent&&!(page==='normal'&&p.reserve));if(unresolved.length)throw Error('尚未安置：'+unresolved.slice(0,15).map(p=>p.name).join('、'));const errors=V.validate(next);if(errors.length)throw Error(errors.join('\n'));us.flat().forEach(p=>p.locked=true);if(page==='team'&&currentTeam){next.teamDone=[...new Set([...next.teamDone,currentTeam])];label=currentTeam+'确认';if(allTeams().every(t=>next.teamDone.includes(t))){next.confirmed.team=true;nextPage='couple'}}else{next.confirmed[page]=true;nextPage={internal:'team',team:'couple',couple:'normal',normal:'overview'}[page]}}
 else {const errors=[...V.relationErrors(next),...V.validate(next,true)];if(errors.length)throw Error(errors.join('\n'));next.confirmed.overview=true;label='最终分组确认'}
 next.stage=nextPage;next.revision++;busy=true;if(await saveSnapshot(label,next)){S=next;page=nextPage;selected.clear();currentTeam=allTeams().find(t=>!S.teamDone.includes(t))||'';undoStack=[];redoStack=[];render();toast('已保存阶段快照')} }catch(e){errorBox(e)}finally{busy=false;render()}}
function pendingHtml(pending){const ids=new Set((page==='overview'?pending:stageMembers()).map(p=>p.id)),current=pending.filter(p=>ids.has(p.id)&&matches(p)),other=pending.filter(p=>!ids.has(p.id)&&matches(p));return `<div class="pending-section"><div class="subtext">${page==='overview'?'待安排':page==='team'?esc(currentTeam||'当前团体'):'当前阶段'} · ${current.length} 人</div>${current.map(personChip).join('')||'<div class="empty">本阶段已安排</div>'}</div>${other.length?`<details class="pending-section"><summary>其他人员 · ${other.length}</summary>${other.map(personChip).join('')}</details>`:''}`}
function deferredHtml(){const ps=S.people.filter(p=>p.deferred);return ps.length?`<div class="pool deferred-pool"><div class="paneltitle issue-text">待处理 <span class="badge">${ps.length}</span></div><div class="members">${ps.map(personChip).join('')}</div><button onclick="showDeferred()">检查关联</button></div>`:''}
function showDeferred(){issuePeople=V.issueIds(S);const ps=S.people.filter(p=>p.deferred||issuePeople.has(p.id));modal('待处理关联',`<p class="subtext">暂不参与自动分配。修复关联后会回到待分配，再确认查重及分配阶段。</p><div class="notice">${V.relationErrors(S).map(esc).join('<br>')||'关联已修复'}</div>${ps.map(p=>`<div class="histrow"><span class="issue-text">${esc(p.name)} · ${esc(p.student)}</span><button onclick="editPerson('${p.id}')">修改</button></div>`).join('')}`)}
function allocationControls(done,total){const el=$('allocationControls');if(!el)return;el.innerHTML=`<span>分配中 ${done} / ${total} 批</span><button onclick="animationPaused=!animationPaused;this.textContent=animationPaused?'继续':'暂停'">${animationPaused?'继续':'暂停'}</button><button onclick="animationSkip=true;animationPaused=false">立即完成</button><button onclick="animationCancel=true;animationPaused=false">取消并还原</button>`}
let animationCancel=false;
async function flyUnit(unit,target,duration){if(!duration)return;const destination=document.querySelector(`[data-drop="${target}"]`);if(!destination)return;destination.scrollIntoView({block:'nearest',behavior:'instant'});const first=document.querySelector(`[data-person="${unit[0].id}"]`);first?.scrollIntoView({block:'nearest',behavior:'instant'});const end=destination.getBoundingClientRect();const flights=unit.map((p,i)=>{const source=document.querySelector(`[data-person="${p.id}"]`)||first;if(!source)return Promise.resolve();const r=source.getBoundingClientRect(),clone=source.cloneNode(true);clone.removeAttribute('data-person');clone.classList.add('flying-person');Object.assign(clone.style,{left:r.left+'px',top:r.top+'px',width:r.width+'px',margin:'0'});document.body.appendChild(clone);const animation=clone.animate([{transform:'translate(0,0)',opacity:1},{transform:`translate(${end.left+18+(i%3)*12-r.left}px,${end.top+95+(i%4)*10-r.top}px)`,opacity:.85}],{duration,easing:'ease-in-out',fill:'forwards'});return animation.finished.catch(()=>{}).finally(()=>clone.remove())});destination.classList.add('receiving');await Promise.all(flights);destination.classList.remove('receiving')}
async function autoAssign(){if(busy||!['internal','team','couple','normal'].includes(page))return;if(stageLocked())return unlockStage();if(!S.confirmed.roles)return toast('先确认任职');if(page==='team'&&!currentTeam)return toast('没有待分配团体');const before=V.copy(S),wasDirty=dirty;busy=true;animationPaused=false;animationSkip=false;animationCancel=false;let result,problem;
 try{const next=V.copy(S);result=V.allocate(next,page,currentTeam,Date.now());const candidates=V.units(before).filter(u=>V.eligible(u,page,currentTeam)&&!u.some(p=>p.locked||before.groups.some(g=>g.leader===p.id))).sort((a,b)=>next.people.findIndex(p=>p.id===a[0].id)-next.people.findIndex(p=>p.id===b[0].id));const targetMap=new Map(next.people.map(p=>[p.id,p]));
 if(allocationSpeed!=='instant'&&candidates.length){query='';filter='';selected.clear();S.people.forEach(p=>{if(candidates.some(u=>u.some(x=>x.id===p.id))){p.group=null;p.reserve=false}});dirty=true;document.querySelector('.app').inert=true;const controls=document.createElement('div');controls.id='allocationControls';controls.className='allocation-controls';document.body.appendChild(controls);renderWorkspace();
 for(let i=0;i<candidates.length;i++){allocationControls(i,candidates.length);while(animationPaused&&!animationSkip&&!animationCancel)await new Promise(r=>setTimeout(r,100));if(animationCancel)break;const unit=candidates[i],planned=targetMap.get(unit[0].id),target=planned.group||(planned.reserve?'reserve':'pending');if(target!=='pending'&&!animationSkip){if(planned.group&&pageSize)pageNo=Math.floor(S.groups.findIndex(g=>g.id===planned.group)/pageSize)+1;renderWorkspace();await flyUnit(unit,target,allocationSpeed==='slow'?1100:380)}unit.forEach(p=>{const live=personOf(p.id),to=targetMap.get(p.id);live.group=to.group;live.reserve=to.reserve});const arriving=new Set(unit.map(p=>p.id));S.people=[...S.people.filter(p=>!arriving.has(p.id)),...S.people.filter(p=>arriving.has(p.id))];renderWorkspace();}
 }
 if(animationCancel){S=before;dirty=wasDirty;toast('已取消，恢复分配前状态')}else{S=before;checkpoint();S=next;changed()}
 }catch(e){S=before;dirty=wasDirty;problem=e}finally{document.querySelector('.app').inert=false;$('allocationControls')?.remove();document.querySelectorAll('.flying-person').forEach(el=>el.remove());busy=false;render()}
 if(problem)return errorBox(problem);if(animationCancel)return;if(result.unplaced.length&&page!=='normal')errorBox(Error('仍有 '+result.unplaced.length+' 人无法安置，请调整容量或未锁定安排。'));else toast(page==='normal'?'分配完成，剩余人员已进入储备':'分配完成，可继续手动调整');
}

async function autoRemaining(){if(busy)return;if(pendingImports.length)return errorBox(Error('还有待导入或修改中的表格，请先完成导入。'));busy=true;document.querySelector('.app').inert=true;try{toast('正在生成剩余分配…');await new Promise(resolve=>setTimeout(resolve,30));const plan=V.remainingPlan(S);if(!await saveSnapshot('全自动分配前备份'))return;checkpoint();for(const step of plan.steps){if(!await saveSnapshot(step.label,step.state)){toast('保存失败，已停在最后保存的阶段');return}S=V.copy(step.state)}S=plan.state;page='overview';selected.clear();focusId=null;render();toast(plan.pending?'已生成草案，仍有 '+plan.pending+' 人待处理':'已生成完整分配草案，请在总览检查');}catch(e){errorBox(e)}finally{busy=false;document.querySelector('.app').inert=false;render()}}
function selectedUnitIds(){return new Set(V.units(S).filter(u=>u.some(p=>selected.has(p.id))).flat().map(p=>p.id))}
function moveSelected(target,anchor=null,after=false){mutate(()=>{V.move(S,[...selected],target,anchor,after)});selected.clear();render()}
function toggleLock(){const ids=selectedUnitIds();if(!ids.size)return;const ps=S.people.filter(p=>ids.has(p.id));if(ps.some(leader))return toast('组长位置由任职设置管理');const unlock=ps.every(p=>p.locked);if(unlock&&(S.confirmed.normal||S.confirmed.overview||S.teamDone.length||S.confirmed.internal)){modal('解锁人员',`<p>解锁将使分配阶段需要重新确认，现有位置保留。</p><button class="primary" onclick="unlockSelection()">保存快照并解锁</button>`);return}mutate(()=>ps.forEach(p=>p.locked=!unlock))}
async function unlockSelection(){if(!await saveSnapshot('解锁前备份'))return;const ids=selectedUnitIds();mutate(()=>{['internal','team','couple','normal','overview'].forEach(k=>delete S.confirmed[k]);S.teamDone=[];S.people.filter(p=>ids.has(p.id)&&!leader(p)).forEach(p=>p.locked=false)});closeModal()}
function swapDialog(){if(!selected.size)return toast('先选择人员');modal('交换人员',`<p>选择另一组或储备区的一名成员，其绑定组合会一起交换。</p><select class="wide" id="swapTarget">${S.people.filter(p=>!selected.has(p.id)&&!p.independent).map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(groupOf(p.group)?.name||(p.reserve?'储备':'待分配'))}</option>`).join('')}</select><div class="form-actions"><button class="primary" onclick="doSwap()">交换</button></div>`)}
function doSwap(){const target=$('swapTarget').value;try{const next=V.copy(S);V.swap(next,[...selected],target);checkpoint();S=next;changed();selected.clear();closeModal();render();toast('已交换')}catch(e){errorBox(e)}}
function matches(p){return(!query||p.name.includes(query)||p.student.includes(query))&&(!filter||p.cat===filter)}
function shownGroups(){const n=pageSize||Math.max(1,S.groups.length);pageNo=Math.max(1,Math.min(pageNo,Math.max(1,Math.ceil(S.groups.length/n))));return S.groups.slice((pageNo-1)*n,pageNo*n)}
function visiblePeople(){const gids=new Set(shownGroups().map(g=>g.id));return S.people.filter(p=>(!p.group||gids.has(p.group))&&!p.independent&&matches(p))}
function selectAll(){visiblePeople().forEach(p=>selected.add(p.id));selected=selectedUnitIds();renderWorkspace()}
function personChip(p){const ids=V.units(S).find(u=>u.some(x=>x.id===p.id))||[];const hint=p.name+' · '+V.CATS[p.cat]+' · '+p.student+(ids.length>1?' · 关联：'+ids.map(x=>x.name).join('、'):'');return `<button class="person ${p.cat} ${issuePeople.has(p.id)?'issue-person':''} ${selected.has(p.id)?'chosen':''}" aria-pressed="${selected.has(p.id)}" draggable="true" data-person="${p.id}" data-unit="${esc(ids.map(x=>x.id).sort().join('|'))}" style="${ids.length>1?'border-left:4px solid hsl('+(ids.map(x=>x.id).sort().join('').split('').reduce((h,c)=>(h*31+c.charCodeAt(0))%360,0))+' 55% 55%)':''}" title="${esc(hint)}">${esc(p.name)}${p.photo?' <span title="摄影">📷</span>':''}${p.run?' <span title="小闪电">🏃</span>':''}${p.pairs.length||p.familyTarget||p.partnerTarget||S.people.some(x=>x.familyTarget===p.id||x.partnerTarget===p.id)?' <span title="情侣或家属">🧑‍🤝‍🧑</span>':''}${p.teams.map(t=>` <span title="${esc(t)}" style="color:${colors[Math.max(0,allTeams().indexOf(t))%colors.length]}">⚑</span>`).join('')}${leader(p)?' <span title="小组长">☆</span>':''}${p.locked?' <span title="已锁定">·</span>':''}</button>`}
function ring(n,cap){return `<div class="capacity-ring ${n>=cap?'full':''}" style="--fill:${Math.min(100,n/cap*100)}%" role="img" aria-label="${n}/${cap}人"><span class="capacity-value"><b>${n}</b><small>/${cap}</small></span><span class="capacity-status">${n>cap?'超员 '+(n-cap):n===cap?'已满':'余 '+(cap-n)+' 人'}</span></div>`}
function groupCard(g){const ps=S.people.filter(p=>p.group===g.id);return `<section class="group group-card" data-drop="${g.id}"><div class="ghead"><div class="gtitle"><span class="gnum">${esc(g.no)}组</span><h2>${esc(g.name)}${S.groups.filter(x=>V.normalize(x.no)===V.normalize(g.no)).length>1?'<small class="subposition">子岗位 '+(S.groups.filter(x=>V.normalize(x.no)===V.normalize(g.no)).findIndex(x=>x.id===g.id)+1)+'</small>':''}</h2></div><div class="leaders"><span>组长 <b>${esc(personOf(g.leader)?.name||'未设置')}</b></span><span>区长 <b>${esc(personOf(g.area)?.name||'未设置')}</b></span></div>${ring(ps.length,g.cap)}</div><div class="members">${ps.filter(matches).map(personChip).join('')||'<div class="empty">暂无匹配人员</div>'}</div><div class="gfoot"><span>内部 ${ps.filter(p=>p.cat==='internal'&&!leader(p)).length}　📷 ${ps.filter(p=>p.photo).length}　🏃 ${ps.filter(p=>p.run).length}</span><span><button onclick="groupList('${g.id}')">名单</button><button onclick="openExport('${g.id}')">导出 ↗</button></span></div></section>`}
function renderStats(){
 const assigned=S.people.filter(p=>p.group).length,pending=S.people.filter(p=>!p.group&&!p.reserve&&!p.independent&&!p.deferred).length;
 const total=S.people.length,demand=S.groups.reduce((sum,g)=>sum+g.cap,0),reserve=S.people.filter(p=>p.reserve).length;const dial=(n,label,denominator=total)=>`<div class="summary-dial"><div class="mini-ring" style="--fill:${denominator?Math.min(100,n/denominator*100):0}%"><b>${n}<small>/${denominator}</small></b></div><span>${label}</span></div>`;
 $('stats').innerHTML=dial(assigned,'已分配 / 名单')+dial(assigned,'已分配 / 总需求',demand)+`<span class="subtext">储备 ${reserve} 人</span><button class="subtle" onclick="showWithdrawn()">放弃参加 ${(S.withdrawn||[]).length} 人</button>`;
}
