 $('footerActions').innerHTML=`<span class="subtext">${S.people.filter(p=>p.independent).length?S.people.filter(p=>p.independent).length+' 位区长独立管理':''}</span>${S.people.some(p=>p.deferred)?`<button class="issue-text" onclick="showDeferred()">待处理 ${S.people.filter(p=>p.deferred).length} 人</button>`:''}<span class="spacer"></span><span class="save-state" id="saveState">${dirty?'有未保存的修改':history.length?'已保存 '+history[0].time.split(' ').pop():'尚未保存'}</span><button onclick="backup()">备份</button>${page==='export'?'':`<button class="primary" onclick="confirmStage()" ${busy?'disabled':''}>${stageLocked()?'重新确认并保存':'确认并继续'} →</button>`}`;
