function setView(v){listView=v;renderWorkspace()}
function renderWorkspace(){renderStats();issuePeople=V.issueIds(S);if(!['internal','team','couple','normal','overview'].includes(page))return;const shown=shownGroups(),pages=Math.max(1,Math.ceil(S.groups.length/(pageSize||Math.max(1,S.groups.length))));const pending=S.people.filter(p=>!p.group&&!p.independent&&!p.reserve&&!p.deferred),reserve=S.people.filter(p=>p.reserve);
 $('mainContent').innerHTML=`${page==='team'?`<div class="team-strip"><label>当前团体 <select onchange="currentTeam=this.value;selected.clear();renderWorkspace()">${allTeams().map(t=>`<option value="${esc(t)}" ${t===currentTeam?'selected':''}>${esc(t)}${S.teamDone.includes(t)?' ✓':''}</option>`).join('')}</select></label><span class="subtext">已确认 ${S.teamDone.length} / ${allTeams().length}</span></div>`:''}<div class="toolbar"><label class="search">⌕ <input id="search" aria-label="搜索姓名或学号" placeholder="姓名 / 学号" value="${esc(query)}" oninput="query=this.value;refreshCards()" onkeydown="if(event.key==='Enter'){event.preventDefault();jumpToSearch()}"></label><select aria-label="筛选来源" onchange="filter=this.value;renderWorkspace()"><option value="">全部来源</option>${Object.entries(V.CATS).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v}</option>`).join('')}</select><span class="spacer"></span><button onclick="undo()" ${undoStack.length?'':'disabled'}>↶ 撤销</button><button onclick="redo()" ${redoStack.length?'':'disabled'}>↷</button><button onclick="toast('直接选择姓名，拖拽或批量移动即可')">人工接管</button>${page!=='overview'?`<select aria-label="分配速度" onchange="allocationSpeed=this.value"><option value="instant" ${allocationSpeed==='instant'?'selected':''}>即时</option><option value="normal" ${allocationSpeed==='normal'?'selected':''}>正常速度</option><option value="slow" ${allocationSpeed==='slow'?'selected':''}>慢速演示</option></select><button id="autoButton" class="primary" onclick="autoAssign()" ${busy?'disabled':''}>分配未锁定人员</button>`:''}${stageLocked()?'<button onclick="unlockStage()">修改本阶段</button>':''}</div><div class="legend"><span><i style="background:#a7bfee"></i>内部</span><span><i style="background:#bba1de"></i>团体</span><span><i style="background:#e8afc5"></i>情侣</span><span><i style="background:#e6bd8c"></i>家属</span><span><i style="background:#b8c0ce"></i>普通</span><span class="hint">点击多选 · 拖拽排序 · 跨组移动</span></div><div class="batchbar" id="batchbar"></div><div class="content ${listView?'listview':''}"><div class="group-area"><div class="pagination"><span>共 ${S.groups.length} 组</span><div class="controls"><label>每页 <select aria-label="每页展示组数" onchange="setPageSize(this.value)">${[1,2,4,6,8,0].map(n=>`<option value="${n}" ${pageSize===n?'selected':''}>${n?n+' 组':'全部'}</option>`).join('')}</select></label><button aria-label="上一页" ${pageNo===1?'disabled':''} onclick="changePage(-1)">‹</button>${pageNo} / ${pages}<button aria-label="下一页" ${pageNo===pages?'disabled':''} onclick="changePage(1)">›</button></div></div><div class="grid" id="groups">${shown.map(groupCard).join('')||'<div class="empty">请先导入或添加小组</div>'}</div></div><aside class="right"><div class="pool" data-drop="pending"><div class="paneltitle">待分配 <span class="badge">${pending.length}</span></div><div class="members" id="pendingMembers">${pendingHtml(pending)}</div></div><div class="detail" id="detail"></div>${deferredHtml()}<div class="pool" data-drop="reserve"><div class="paneltitle">储备 <span class="badge">${reserve.length}</span></div><div class="members" id="reserveMembers">${reserve.filter(matches).map(personChip).join('')||'<div class="empty">暂无储备</div>'}</div></div></aside></div>`;renderSelection();bindDrag();
}
function jumpToSearch(){const q=query.trim();if(!q)return;const hits=S.people.filter(p=>p.name.includes(q)||p.student.includes(q));const p=hits.find(p=>p.name===q||p.student===q)||hits[0];if(!p)return toast('没有找到匹配人员');filter='';focusId=p.id;const index=S.groups.findIndex(g=>g.id===p.group);if(index>=0)pageNo=Math.floor(index/(pageSize||S.groups.length))+1;renderWorkspace();const target=[...document.querySelectorAll('[data-person]')].find(el=>el.dataset.person===p.id);const card=index>=0?[...document.querySelectorAll('[data-drop]')].find(el=>el.dataset.drop===p.group):target;card?.scrollIntoView({behavior:'smooth',block:'center'});target?.classList.add('search-hit');if(!target)toast('该人员在待处理名单中');else if(hits.length>1)toast('找到 '+hits.length+' 人，已定位 '+p.name)}
function refreshCards(){const search=$('search'),cursor=search.selectionStart;renderWorkspace();$('search').focus();$('search').setSelectionRange(cursor,cursor)}
function personInfo(p,expanded=false){const peers=V.units(S).find(u=>u.some(x=>x.id===p.id))||[p];const fields=[...Object.entries(extraValues(p)),['学号',p.student],['邮箱',p.email],['是否小组长',p.intent],['情侣关联',personOf(p.partnerTarget)?.name||p.partnerName],['家属关联',personOf(p.familyTarget)?.name||p.familyName],['团体',p.teams.join('、')],['配对编号',p.pairs.join('、')],['标志',[p.photo?'📷 摄影':'',p.run?'🏃 小闪电':''].filter(Boolean).join(' / ')]];const originals=p.origins.map(o=>{const src=S.sources.find(x=>x.id===o.sourceId);const raw=src?.records?.find(r=>r.origins?.some(x=>x.row===o.row&&x.file===o.file&&x.sheet===o.sheet))?.raw||p.raw;return `<details><summary>${esc(o.file+' / '+o.sheet+' · 第'+o.row+'行')}</summary><dl>${Object.entries(raw).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)||'—'}</dd>`).join('')}</dl></details>`}).join('');return `<div class="person-info">${fields.filter(([,v])=>v).map(([k,v])=>`<div class="info-row"><span>${esc(k)}</span><span>${esc(v)}</span></div>`).join('')}<details ${expanded?'open':''}><summary>关联成员（${peers.length-1}）</summary>${peers.filter(x=>x.id!==p.id).map(x=>`<div class="info-row"><button type="button" class="${issuePeople.has(x.id)?'issue-text':''}" onclick="editPerson('${x.id}')">${esc(x.name)}</button><span>${esc(x.student)} · ${V.CATS[x.cat]}<br>${esc(groupOf(x.group)?.name||'待分配')}</span></div>`).join('')||'<p class="subtext">无已确认的关联成员</p>'}</details><details ${expanded?'open':''}><summary>原始表单与全部字段</summary>${originals||`<pre>${esc(JSON.stringify(p.raw,null,2))}</pre>`}</details></div>`}
function renderSelection(){selected=new Set([...selected].filter(id=>personOf(id)));const ps=S.people.filter(p=>selected.has(p.id));$('batchbar').innerHTML=`<span>${selected.size?'已选 '+selected.size+' 人':'点击姓名选择人员'}</span><button onclick="selectAll()">全选本页</button>${selected.size?'<button onclick="selected.clear();renderWorkspace()">取消</button><button onclick="swapDialog()">交换</button><button onclick="toggleLock()">锁定 / 解锁</button>':''}`;const p=personOf(focusId)||ps[0];$('detail').innerHTML=`<div class="paneltitle">${selected.size>1?'批量调整':'人员详情'}</div>${p?`<div class="detail-body"><div class="avatar">${esc(p.name.slice(-1))}</div><strong>${esc(p.name)}</strong></div><div class="details"><span>类别</span><span>${V.CATS[p.cat]}${p.autoCoupleFrom?'（自动匹配）':''}</span></div><div class="details"><span>关联</span><span>${esc([...p.teams,...p.pairs,p.partnerName,p.familyName].filter(Boolean).join(' / ')||'无')}</span></div>${personInfo(p)}`:'<div class="empty">选择姓名查看</div>'}<select id="moveTarget" aria-label="移动目标"><option value="">移动到…</option>${S.groups.map(g=>`<option value="${g.id}">${esc(g.no+'组 · '+g.name)}</option>`).join('')}<option value="pending">待分配</option><option value="reserve">储备</option></select><button class="primary" ${selected.size?'':'disabled'} onclick="if($('moveTarget').value)moveSelected($('moveTarget').value)">移动所选</button>${p?`<button onclick="editPerson('${p.id}')">编辑人员</button>`:''}`}
function highlightUnit(key,on){document.querySelectorAll('[data-unit]').forEach(el=>{if(el.dataset.unit===key)el.classList.toggle('unit-hover',on)})}
function clearDropHints(){document.querySelectorAll('.drop-allowed,.drop-blocked').forEach(el=>{el.classList.remove('drop-allowed','drop-blocked');el.removeAttribute('data-drop-reason')})}
function showDropHints(){clearDropHints();document.querySelectorAll('.group-card[data-drop]').forEach(el=>{try{V.move(V.copy(S),[...selected],el.dataset.drop);el.classList.add('drop-allowed');el.dataset.dropReason='可移入'}catch(e){el.classList.add('drop-blocked');el.dataset.dropReason=e.message}})}
function bindDrag(){document.querySelectorAll('[data-person]').forEach(el=>{el.onmouseenter=()=>highlightUnit(el.dataset.unit,true);el.onmouseleave=()=>highlightUnit(el.dataset.unit,false);el.ondragend=()=>clearDropHints();el.onclick=e=>{const id=el.dataset.person;focusId=id;if(e.shiftKey&&lastSelected){const ps=visiblePeople(),a=ps.findIndex(p=>p.id===id),b=ps.findIndex(p=>p.id===lastSelected);if(a>=0&&b>=0)ps.slice(Math.min(a,b),Math.max(a,b)+1).forEach(p=>selected.add(p.id));}else{const ids=V.units(S).find(u=>u.some(p=>p.id===id)).map(p=>p.id);if(selected.has(id))ids.forEach(x=>selected.delete(x));else ids.forEach(x=>selected.add(x))}selected=selectedUnitIds();lastSelected=id;renderWorkspace()};el.ondragstart=e=>{if(!selected.has(el.dataset.person))selected=new Set([el.dataset.person]);selected=selectedUnitIds();e.dataTransfer.setData('text/plain',JSON.stringify([...selected]));e.dataTransfer.effectAllowed='move';showDropHints()};el.ondragover=e=>{e.preventDefault();e.stopPropagation();document.querySelectorAll('.drop-before,.drop-after').forEach(x=>x.classList.remove('drop-before','drop-after'));if(selected.has(el.dataset.person))return;const r=el.getBoundingClientRect();el.classList.add(e.clientX<r.left+r.width/2?'drop-before':'drop-after')};el.ondragleave=()=>el.classList.remove('drop-before','drop-after');el.ondrop=e=>{e.preventDefault();e.stopPropagation();const p=personOf(el.dataset.person),r=el.getBoundingClientRect();moveSelected(personLocation(p),p.id,e.clientX>=r.left+r.width/2)};el.onkeydown=e=>{if(e.altKey&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const p=personOf(el.dataset.person);selected=new Set([p.id]);selected=selectedUnitIds();const index=S.people.indexOf(p),ps=S.people.filter(x=>personLocation(x)===personLocation(p)&&!selected.has(x.id)),other=e.key==='ArrowLeft'?[...ps].reverse().find(x=>S.people.indexOf(x)<index):ps.find(x=>S.people.indexOf(x)>index);if(other){moveSelected(personLocation(p),other.id,e.key==='ArrowRight');document.querySelector('[data-person="'+p.id+'"]')?.focus()}}}});document.querySelectorAll('[data-drop]').forEach(el=>{el.ondragover=e=>{e.preventDefault();el.classList.add('dragover')};el.ondragleave=()=>el.classList.remove('dragover');el.ondrop=e=>{e.preventDefault();el.classList.remove('dragover');clearDropHints();moveSelected(el.dataset.drop)};el.ondragend=()=>renderWorkspace()})}
function groupList(id){const g=groupOf(id);modal(g.no+'组 · '+g.name,`<p>组长 ${esc(personOf(g.leader)?.name||'未设置')}　区长 ${esc(personOf(g.area)?.name||'未设置')}</p><div class="tablewrap"><table><thead><tr><th>姓名</th><th>学号</th><th>来源</th><th>角色</th></tr></thead><tbody>${S.people.filter(p=>p.group===id).map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.student)}</td><td>${V.CATS[p.cat]}</td><td>${leader(p)?'组长':''}${p.area?' 区长':''}</td></tr>`).join('')}</tbody></table></div>`)}
const FIELD_NAMES={name:'姓名',student:'学号',email:'邮箱',intent:'是否小组长',photo:'摄影标志',run:'小闪电标志',team:'团体名称',pair:'配对编号（可选）',family:'关联志愿者姓名',partner:'情侣姓名（可选）',no:'组号',groupName:'小组名称',cap:'总名额',region:'所属区域'};
const ALIASES={name:['姓名','志愿者姓名','名字'],student:['学号','学生学号','学生编号'],email:['邮箱','电子邮箱','邮件'],intent:['是否小组长','是否报名小组长','是否报名组长','报名小组长','报名意向','报名职位','意向'],photo:['摄影标志','摄影','是否摄影'],run:['小闪电标志','小闪电','是否小闪电'],team:['团体名称','组织名称','团体','组织'],pair:['配对编号','情侣编号','组合编号'],family:['关联志愿者姓名','关联志愿者','志愿者名字'],partner:['伴侣姓名','情侣姓名','对象姓名','另一半姓名'],no:['组号','小组号'],groupName:['小组名称','岗位名称','岗位'],cap:['总名额','小组人数','人数','名额','需求人数','年需求'],region:['所属区域','区域']};
function headerClean(s){return V.normalize(s).replace(/[\s\n\r]/g,'').replace(/的/g,'')}
function inferMap(headers){return Object.fromEntries(Object.entries(ALIASES).map(([k,names])=>{const scores=headers.map(h=>{const text=headerClean(h).replace(/^Q?\d+[.、．:：]?/i,'');if(k==='name'&&/关联|伴侣|情侣|对象|另一半|家属|拼音|英文/.test(text))return 0;if(['family','partner'].includes(k)&&/性别|学号|电话|邮箱|手机|拼音|英文/.test(text))return 0;return Math.max(0,...names.map(alias=>{const a=headerClean(alias);return text===a?1000+a.length:text.includes(a)?a.length*10:0}))});const best=Math.max(0,...scores);return [k,best?scores.indexOf(best):-1]}))}
function categoryHint(text){const name=V.normalize(text).replace(/\.(xlsx?|csv)$/i,'');const hits=[['groups',/小组信息|需求表|需求名单|岗位需求|名额表/],['family',/家属/],['couple',/情侣/],['internal',/内部/],['team',/团体|团队|学生会|协会|社团/],['normal',/普通/]].filter(([,pattern])=>pattern.test(name)).map(([type])=>type);if(hits.length===1)return {type:hits[0],recognized:true};if(hits.length>1)return {type:'normal',recognized:false,ambiguous:true};return {type:'normal',recognized:false}}
function inferCategory(file,name){const sheet=categoryHint(name);if(sheet.recognized||sheet.ambiguous)return {...sheet,source:'工作表名'};const filename=categoryHint(file);if(filename.recognized||filename.ambiguous)return {...filename,source:'文件名'};return {type:'normal',recognized:false,source:''}}
function inferType(name){return inferCategory('',name).type}
function initializeImportCategory(sheet){if(sheet.typeInferenceChecked||sheet.typeConfirmed)return;const hint=inferCategory(sheet.file,sheet.name);if(hint.recognized){sheet.type=hint.type;sheet.typeConfirmed=true;sheet.typeAutoSource=hint.source}sheet.typeInferenceChecked=true}
function bool(v){const text=V.normalize(v).toLowerCase();if(/不|未|否|无|取消|放弃|暂缓|考虑|待定|尚未/.test(text))return false;return text.includes('报名')||['是','1','true','yes','√','✓','报名','摄影','小闪电'].includes(text)}
function workbookSheets(bytes,file){const fileId=V.uid(),wb=XLSX.read(bytes,{type:'array',cellDates:false});return wb.SheetNames.map(name=>{const ws=wb.Sheets[name],rows=XLSX.utils.sheet_to_json(ws,{header:1,defval:'',raw:false,blankrows:true});let best=0,score=-1;rows.slice(0,12).forEach((r,i)=>{let map=inferMap(r),n=Object.values(map).filter(x=>x>=0).length;if(n>score){best=i;score=n}});return {id:V.uid(),fileId,file,name,rows,merges:ws['!merges']||[],header:best,type:inferCategory(file,name).type,typeConfirmed:inferCategory(file,name).recognized,typeAutoSource:inferCategory(file,name).recognized?inferCategory(file,name).source:'',typeInferenceChecked:true,teamName:name,map:inferMap(rows[best]||[])}})}
async function handleFiles(files){if(!files.length)return;if(S.confirmed.roles&&!confirm('新增名单会使查重及分配确认失效，现有位置会保留待检查。继续？'))return;busy=true;try{for(const f of files){if(f.size>30*1024*1024)throw Error(f.name+' 超过30MB，请拆分文件');pendingImports.push(...workbookSheets(await f.arrayBuffer(),f.name))}renderImport();toast('已读取文件，请逐张确认类别和字段')}catch(e){errorBox(e)}finally{busy=false;$('files').value=''}}
function renderImport(){const current=pendingImports[0];if(current)initializeImportCategory(current);$('mainContent').innerHTML=`<div class="section-card"><div class="section-top"><h2>上传名单</h2><div><button onclick="downloadTemplates(false)">下载模板</button> <button onclick="downloadTemplates(true)">测试样例</button></div></div><div class="dropzone" id="fileDrop"><span style="font-size:30px;color:var(--blue)">↥</span><h3>将表格拖到这里</h3><span class="subtext">Excel / CSV · 支持多个文件</span><br><button class="primary" onclick="$('files').click()" style="margin-top:14px">选择文件</button></div></div>${current?`<div class="section-card"><div class="section-top"><h2>${current.editingSourceId?'修改导入':'导入预览'}</h2><span class="badge">还有 ${pendingImports.length} 张表</span></div>${current.editingSourceId?`<p class="subtext">可修改类别、表头、对应列，也可点击预览中的单元格修改内容，然后点击“预览修改”。应用前，已导入数据保持不变。${current.reconstructed?'此旧表由已保存的原始字段重建，表头为第 1 行，原文件的空行和合并格式无法还原。':''}</p>`:''}<div class="formrow"><label>工作表<select class="wide" onchange="switchPending(Number(this.value))">${pendingImports.map((p,i)=>`<option value="${i}">${esc(p.file+' / '+p.name)}</option>`).join('')}</select></label><label>类别<span class="category-choice"><select class="wide ${current.typeConfirmed?'mapped':'unmapped'}" id="importType" title="${current.typeAutoSource?'已根据'+current.typeAutoSource+'识别，可手动修改':current.typeConfirmed?'类别已确认':'未识别类别，请确认'}" onchange="confirmImportType(this.value)">${Object.entries({...V.CATS,groups:'小组信息'}).map(([k,v])=>`<option value="${k}" ${current.type===k?'selected':''}>${v}</option>`).join('')}</select>${current.typeConfirmed?'<span class="category-confirmed" aria-label="类别已确认">✓</span>':'<button type="button" class="category-confirm" onclick="confirmImportType()" title="确认推荐类别">确认</button>'}</span></label><label>表头行<input type="number" min="1" max="${current.rows.length}" value="${current.header+1}" onchange="changeHeader(this.value)"></label>${current.type==='team'?`<label>默认团体名<input id="importTeam" value="${esc(current.teamName)}" oninput="pendingImports[0].teamName=this.value"></label>`:''}</div><button class="subtle" onclick="rematchImportColumns()">重新匹配列</button><button onclick="newImportLabel()">＋ 新增标签</button><div class="mapping">${(current.type==='groups'?['no','groupName','cap','region']:['name','student','email','intent','photo','run','team','pair','family','partner']).map(key=>`<label>${FIELD_NAMES[key]}<select class="${current.map[key]>=0?'mapped':'unmapped'}" title="${current.map[key]>=0?'已匹配':'未选择'}" onchange="pendingImports[0].map['${key}']=Number(this.value);this.className=Number(this.value)>=0?'mapped':'unmapped';this.title=Number(this.value)>=0?'已匹配':'未选择'"><option value="-1">${key==='no'?'自动编号':'不使用'}</option>${(current.rows[current.header]||[]).map((h,i)=>`<option value="${i}" ${current.map[key]===i?'selected':''}>${esc(h||'第'+(i+1)+'列')}</option>`).join('')}</select></label>`).join('')}${importLabelsHtml(current)}</div><p class="subtext">绿：已匹配／已确认 · 黄：未选择／待确认　共 ${Math.max(0,current.rows.length-current.header-1)} 行，可上下及左右滚动</p><div class="tablewrap import-preview" tabindex="0" aria-label="完整表格预览"><table><thead><tr>${(current.rows[current.header]||[]).map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${current.rows.slice(current.header+1).map((row,rowIndex)=>`<tr>${(current.rows[current.header]||[]).map((_,i)=>`<td ${(current.editingSourceId||current.addedColumns?.includes(i))?`contenteditable="plaintext-only" aria-label="第${rowIndex+current.header+2}行 ${esc(current.rows[current.header][i]||'第'+(i+1)+'列')}" onblur="updateImportCell(${rowIndex+current.header+1},${i},this.textContent)"`:''}>${esc(row[i]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="form-actions">${current.editingSourceId?'<button onclick="cancelImportEdit()">取消修改</button>':'<button onclick="cancelPendingFile()">取消此文件</button><button onclick="pendingImports.shift();renderImport()">跳过此表</button>'}<button class="primary" onclick="commitSheet()">${current.editingSourceId?'预览修改':'确认导入此表'}</button></div></div>`:''}<div class="section-card"><div class="section-top"><h2>已导入</h2><div><button onclick="undoLastImport()" ${S.sources.length?'':'disabled'}>撤销最近导入</button> <button onclick="openRoster()">查看人员</button></div></div>${importedFilesHtml()}</div>`;const drop=$('fileDrop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover')};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragover');handleFiles([...e.dataTransfer.files])}}
function confirmImportType(value){const sheet=pendingImports[0];if(!sheet)return;sheet.type=value||sheet.type;sheet.typeConfirmed=true;sheet.typeAutoSource='';renderImport()}
function switchPending(i){const [p]=pendingImports.splice(i,1);pendingImports.unshift(p);renderImport()}
function addImportLabel(sheet,name){name=V.normalize(name);if(!name||name.length>100)throw Error('标签名称须为1～100字');if(Object.values(FIELD_NAMES).some(n=>n.replace(/（.*?）/g,'')===name)||(sheet.customLabels||[]).some(x=>x.name===name))throw Error('该标签已存在');const headers=sheet.rows[sheet.header]||[],clean=headerClean(name);let col=headers.findIndex(h=>headerClean(h)===clean);if(col<0){const matches=headers.map((h,i)=>({h:headerClean(h),i})).filter(x=>x.h.includes(clean));if(matches.length===1)col=matches[0].i}sheet.customLabels??=[];sheet.customLabels.push({id:V.uid(),name,col});return col}
function newImportLabel(){if(busy||!pendingImports[0])return;const sheet=pendingImports[0];modal('新增字段标签',`<form id="newLabelForm"><label class="field">标签名称<input name="labelName" required maxlength="100" placeholder="例如：手机号、学院、服装尺码"></label><p class="subtext">添加后，选择表格中对应的列。不会新增 Excel 数据列。</p><div class="form-actions"><button type="button" onclick="closeModal()">取消</button><button class="primary">添加标签</button></div></form>`);$('newLabelForm').onsubmit=e=>{e.preventDefault();if(busy||pendingImports[0]!==sheet)return;try{addImportLabel(sheet,new FormData(e.target).get('labelName'));changed();closeModal();renderImport();toast('已添加标签，请确认对应列')}catch(error){toast(error.message)}}}
function importLabelsHtml(sheet){return (sheet.customLabels||[]).map((field,i)=>`<label><span>${esc(field.name)} <button type="button" class="subtle" aria-label="删除${esc(field.name)}标签" onclick="removeImportLabel(${i})">×</button></span><select class="${field.col>=0?'mapped':'unmapped'}" onchange="pendingImports[0].customLabels[${i}].col=Number(this.value);changed();this.className=Number(this.value)>=0?'mapped':'unmapped'"><option value="-1" ${field.col<0?'selected':''}>不使用</option>${(sheet.rows[sheet.header]||[]).map((h,j)=>`<option value="${j}" ${field.col===j?'selected':''}>${esc(h||'第'+(j+1)+'列')}</option>`).join('')}</select></label>`).join('')}
function removeImportLabel(index){if(busy)return;pendingImports[0]?.customLabels?.splice(index,1);changed();renderImport()}
function customLabelValues(sheet,row){return Object.fromEntries((sheet.customLabels||[]).filter(f=>f.col>=0).map(f=>[f.name,V.normalize(row[f.col])]))}
function extraValues(p){const fields={};for(const o of p.origins||[]){const source=S.sources.find(x=>x.id===o.sourceId);const record=source?.records?.find(r=>(r.origins||[]).some(x=>x.row===o.row&&x.file===o.file&&x.sheet===o.sheet));Object.assign(fields,record?.customFields||{})}return {...fields,...(p.customFields||{})}}
function rematchCustomLabels(sheet){const names=(sheet.customLabels||[]).map(f=>f.name);sheet.customLabels=[];names.forEach(name=>addImportLabel(sheet,name))}
function rematchImportColumns(){const sheet=pendingImports[0];if(!sheet||busy)return;sheet.map=inferMap(sheet.rows[sheet.header]||[]);rematchCustomLabels(sheet);changed();renderImport();toast('已重新匹配列，请核对结果')}
function changeHeader(n){const p=pendingImports[0];p.header=Math.max(0,Math.min(p.rows.length-1,Number(n)-1));p.map=inferMap(p.rows[p.header]||[]);rematchCustomLabels(p);renderImport()}
function nextGroupNumber(){return S.groups.reduce((max,g)=>/^\d+$/.test(g.no)&&Number.isSafeInteger(Number(g.no))?Math.max(max,Number(g.no)):max,0)+1}
function parseSheet(sheet){const {map:m,header,type}=sheet;const val=(row,k)=>m[k]>=0?V.normalize(row[m[k]]):'';const rows=V.copy(sheet.rows);if(type==='groups'){
 for(const merge of sheet.merges){for(let r=merge.s.r;r<=merge.e.r;r++)for(let c=merge.s.c;c<=merge.e.c;c++){if(r>header&&[m.no,m.region].includes(c)){rows[r]??=[];rows[r][c]=rows[merge.s.r]?.[merge.s.c]||''}}}
 if(m.cap<0||m.groupName<0)throw Error('请匹配小组名称、总名额；组号可自动编号');
 const collected=new Map(),numberKey=no=>/^\d+$/.test(no)?String(Number(no)):no;
 const reserved=new Set([...S.groups.map(g=>g.no),...rows.slice(header+1).map(row=>val(row,'no')).filter(Boolean)].map(numberKey));let next=nextGroupNumber();
 rows.slice(header+1).forEach((row,i)=>{if(sheet.excludedRows?.includes(i+header+2))return;let no=val(row,'no'),name=val(row,'groupName'),rawCap=val(row,'cap');
  if(!name||/合计|总计|小计/.test(name)||/合计|总计|小计/.test(no))return;
  const cap=Number(rawCap);if(!Number.isInteger(cap)||cap<1)throw Error('第'+(i+header+2)+'行名额无效');
  if(!no){const old=sheet.editingSourceId?S.sources.find(src=>src.id===sheet.editingSourceId&&src.type==='groups'):null;const previous=old?.records?.find(g=>g.importRow===i+header+2);if(previous)no=previous.no;else{while(reserved.has(String(next)))next++;no=String(next++);}reserved.add(no)}
  collected.set(V.uid(),{id:V.uid(),no,name,cap,importRow:i+header+2,region:val(row,'region'),customFields:customLabelValues(sheet,row),leader:null,area:null});
 });return [...collected.values()]}
 if(m.name<0)throw Error('请先匹配姓名列');const headers=rows[header]||[];return rows.slice(header+1).flatMap((row,i)=>{const name=val(row,'name');if(!name)return [];if(['合计','总计','姓名'].includes(name))return [];const team=val(row,'team')||(type==='team'?V.normalize(sheet.teamName):''),pair=val(row,'pair');return [V.person({name,student:val(row,'student'),email:val(row,'email'),intent:val(row,'intent')||'不报名',cat:type,photo:bool(val(row,'photo')),run:bool(val(row,'run')),teams:team?[team]:[],pairs:pair?[pair]:[],familyName:type==='couple'?'':val(row,'family'),partnerName:val(row,'partner')||(type==='couple'?val(row,'family'):''),origins:[{file:sheet.file,sheet:sheet.name,row:i+header+2}],customFields:customLabelValues(sheet,row),raw:Object.fromEntries(headers.map((h,j)=>[V.normalize(h)||'列'+(j+1),V.normalize(row[j])]))})]})}
function commitParsed(sheet,records){if(sheet.editingSourceId)return reviewImportEdit(sheet,records);const sourceId=sheet.id||V.uid();stampRecords(records,sheet.type,sourceId);const ok=mutate(()=>{if(sheet.type==='groups')S.groups.push(...records);else S.people.push(...records.filter(p=>!wasWithdrawn(S,p)));S.sources.push(sourceManifest(sheet,records,sourceId));},true);if(!ok)return;pendingImports.shift();closeModal();render();toast('已导入 '+records.length+' 条，可在“已导入”列表撤销')}
function importSheetCopy(sheet){const result=V.copy(sheet);delete result.editingSourceId;delete result.reconstructed;return result}
function sourceManifest(sheet,records,id){return {id,fileId:sheet.fileId||sheet.file,file:sheet.file,sheet:sheet.name,type:sheet.type,count:records.length,records:V.copy(records),importSheet:importSheetCopy(sheet)}}
function stampRecords(records,type,sourceId){records.forEach(record=>{if(type==='groups')record.sourceId=sourceId;else{record.primarySourceId=sourceId;record.origins=record.origins.map(o=>({...o,sourceId}))}})}
function rebuildImportSheet(source){
 if(source.importSheet)return V.copy(source.importSheet);
 if(!source.records?.length)throw Error('这份旧记录没有保存原始字段，请重新上传原文件，或从历史恢复导入前版本。');
 let headers,rows,map;
 if(source.type==='groups'){
  headers=['组号','小组名称','总名额','所属区域'];rows=[headers,...source.records.map(g=>[g.no,g.name,g.cap,g.region||''])];map=inferMap(headers);
 }else{
  headers=[...new Set(source.records.flatMap(p=>Object.keys(p.raw||{})))];
  if(!headers.length)throw Error('旧记录缺少原始列，请重新上传原文件。');
  rows=[headers];source.records.forEach(p=>rows.push(headers.map(h=>p.raw[h]??'')));map=inferMap(headers);
  // Recover custom headers by comparing the original imported values, only when unambiguous.
  const fields={name:'name',student:'student',email:'email',intent:'intent',partner:'partnerName',family:source.type==='couple'?'partnerName':'familyName'};
  for(const [field,key] of Object.entries(fields)){if(map[field]>=0)continue;const populated=source.records.filter(p=>p[key]);if(!populated.length)continue;const candidates=headers.map((h,i)=>({h,i})).filter(({h})=>populated.every(p=>V.normalize(p.raw[h])===V.normalize(p[key])));if(candidates.length===1)map[field]=candidates[0].i;}
 }
 return {id:source.id,fileId:source.fileId||source.file,file:source.file,name:source.sheet,type:source.type,typeConfirmed:true,typeInferenceChecked:true,header:0,rows,merges:[],map,teamName:source.records.find(p=>p.teams?.length)?.teams[0]||source.sheet,reconstructed:true};
}
function editImportedSheet(id){if(busy)return;try{
 const source=S.sources.find(x=>x.id===id);if(!source)throw Error('这张表已被撤销，请刷新已导入列表');
 let draft=pendingImports.find(p=>p.editingSourceId===id);
 if(draft){pendingImports=pendingImports.filter(p=>p!==draft)}else{draft=rebuildImportSheet(source);draft.id=V.uid();draft.editingSourceId=id;draft.typeConfirmed=true;draft.typeInferenceChecked=true;}
 pendingImports.unshift(draft);page='import';changed();render();document.querySelector('#importType')?.scrollIntoView({block:'center',behavior:'smooth'});
 }catch(e){errorBox(e)}}
function updateImportCell(row,col,value){const sheet=pendingImports[0];if(busy||!sheet||(!sheet.editingSourceId&&!sheet.addedColumns?.includes(col)))return;sheet.rows[row]??=[];sheet.rows[row][col]=String(value??'');changed()}
function cancelImportEdit(){if(busy||!pendingImports[0]?.editingSourceId)return;pendingImports.shift();changed();renderImport();toast('已取消修改，已导入数据保持不变')}
function wasWithdrawn(state,p){return (state.withdrawn||[]).some(w=>(w.student&&p.student&&w.student===p.student)||w.id===p.id||(w.origins||[]).some(a=>(p.origins||[]).some(b=>a.sourceId&&a.sourceId===b.sourceId&&a.row===b.row)))}
function planImportEdit(state,sheet,records){
 const source=state.sources.find(x=>x.id===sheet.editingSourceId);if(!source)throw Error('原导入表已被撤销，不能应用此次修改');
 const plan=V.removeSources(state,[source.id]),next=plan.state,newRecords=V.copy(records);
 stampRecords(newRecords,sheet.type,source.id);
 if(sheet.type==='groups')next.groups.push(...newRecords);else next.people.push(...newRecords.filter(p=>!wasWithdrawn(state,p)));
 const manifest=sourceManifest(sheet,newRecords,source.id);manifest.importSheet.id=source.id;
 const index=state.sources.findIndex(x=>x.id===source.id);next.sources.splice(index,0,manifest);
 V.resolveFamily(next);V.refreshDeferred(next);next.revision=state.revision+1;
 return {state:next,stats:plan.stats,source,recordCount:newRecords.length};
}
function reviewImportEdit(sheet,records){
 const plan=planImportEdit(S,sheet,records),revision=S.revision;
 modal('确认修改导入',`<p>${esc(sheet.file)} / ${esc(sheet.name)}</p><div class="notice">${esc(plan.source.type==='groups'?'小组信息':V.CATS[plan.source.type])} → ${esc(sheet.type==='groups'?'小组信息':V.CATS[sheet.type])} · ${plan.source.count} 条 → ${records.length} 条<br>替换这张表的导入记录，不会追加一份。${plan.stats.retained?'已合并的 '+plan.stats.retained+' 人保留其他来源，需重新查重。':''}</div><p class="subtext">将按新的导入设置重建此表记录，此表相关的人员安排或任职需重新检查；查重及后续阶段需要重新确认。其他表的数据保留。修改前后均保存历史版本。</p><div class="form-actions"><button onclick="closeModal()">返回修改</button><button class="primary" id="applyImportEdit">应用修改</button></div>`);
 $('applyImportEdit').onclick=()=>applyImportEdit(sheet,records,revision);
}
async function applyImportEdit(sheet,records,revision){if(busy)return false;busy=true;const button=$('applyImportEdit');if(button)button.disabled=true;try{
 if(S.revision!==revision)throw Error('名单已变化，请返回修改页，重新预览后应用');
 const plan=planImportEdit(S,sheet,records),nextPending=pendingImports.filter(p=>p.id!==sheet.id);
 if(!await saveSnapshot('修改导入前 · '+sheet.name))return false;
 if(!await saveSnapshot('修改导入 · '+sheet.name,plan.state,nextPending))return false;
 checkpoint();S=plan.state;pendingImports=nextPending;recoverExport();selected.clear();focusId=null;currentTeam='';page='import';closeModal();render();toast('已应用导入修改，可在历史中恢复');return true;
 }catch(e){errorBox(e);return false}finally{busy=false;render();if(button)button.disabled=false}}

function sourceFileKey(src){return src.fileId||src.file}
function importedFilesHtml(){if(!S.sources.length)return '<div class="empty">暂无名单</div>';const files=new Map();S.sources.forEach(src=>{const key=sourceFileKey(src);if(!files.has(key))files.set(key,[]);files.get(key).push(src)});return [...files.values()].map(rows=>`<div class="import-file"><div class="histrow"><b>${esc(rows[0].file)}</b><button onclick="requestRemoveFile('${rows[0].id}')">撤销此文件</button></div>${rows.map(src=>`<div class="histrow"><div><span>${esc(src.sheet)}</span><br><span class="subtext">${src.type==='groups'?'小组信息':V.CATS[src.type]} · ${src.count} 条</span></div><div><button onclick="editImportedSheet('${src.id}')">修改导入</button> <button onclick="requestRemoveSources(['${src.id}'])">撤销此表</button></div></div>`).join('')}</div>`).join('')}
function undoLastImport(){const src=S.sources.at(-1);if(src)requestRemoveSources([src.id])}
function requestRemoveFile(id){const src=S.sources.find(x=>x.id===id);if(!src)return;const key=sourceFileKey(src);requestRemoveSources(S.sources.filter(x=>sourceFileKey(x)===key).map(x=>x.id),key)}
function requestRemoveSources(ids,fileKey=null){if(busy)return toast('请等待当前操作完成');try{const plan=V.removeSources(S,ids),stats=plan.stats,labels=S.sources.filter(src=>ids.includes(src.id)).map(src=>src.file+' / '+src.sheet);const hasProgress=S.people.some(p=>p.group||p.reserve)||Object.keys(S.confirmed).length>0;modal('撤销导入',`<p>${labels.map(esc).join('<br>')}</p><div class="notice">移除 ${stats.people} 位人员、${stats.groups} 个小组。${stats.retained?' '+stats.retained+' 位合并人员仍有其他来源，将保留并重新核对。':''}${stats.unassigned?' '+stats.unassigned+' 位人员返回待分配。':''}${stats.roles?' '+stats.roles+' 处任职需要重选。':''}</div><p class="subtext">先保存完整快照，历史可恢复。${hasProgress?'查重、任职及后续分配需要重新确认；其他名单与现有位置先保留。':''}原文件不会修改。</p><div class="form-actions"><button onclick="closeModal()">取消</button><button class="primary" id="removeImportConfirm">确认撤销</button></div>`);$('removeImportConfirm').onclick=()=>removeImportedSources(ids,fileKey)}catch(e){modal('需要从历史恢复',`<div class="notice">${esc(e.message)}</div><button class="primary" onclick="showHistory()">打开历史版本</button>`)}}
async function removeImportedSources(ids,fileKey=null){if(busy)return false;busy=true;const button=$('removeImportConfirm');if(button){button.disabled=true;button.textContent='正在保存…'}try{const plan=V.removeSources(S,ids),nextPending=pendingImports.filter(p=>!ids.includes(p.editingSourceId)&&(fileKey===null||sourceFileKey(p)!==fileKey));if(!await saveSnapshot('撤销导入前备份'))return false;plan.state.revision++;if(!await saveSnapshot('撤销导入 · '+ids.length+' 张表',plan.state,nextPending))return false;checkpoint();S=plan.state;pendingImports=V.copy(nextPending);recoverExport();page='import';selected.clear();focusId=null;currentTeam='';closeModal();render();toast('已撤销导入，原状态可从历史恢复');return true}catch(e){errorBox(e);return false}finally{busy=false;render();if(button){button.disabled=false;button.textContent='确认撤销'}}}
async function cancelPendingFile(){if(busy||!pendingImports.length)return false;busy=true;try{const key=sourceFileKey(pendingImports[0]),next=pendingImports.filter(p=>sourceFileKey(p)!==key),count=pendingImports.length-next.length;if(!await saveSnapshot('取消待导入文件前备份'))return false;if(!await saveSnapshot('取消待导入文件',S,next))return false;pendingImports=next;renderImport();toast('已取消 '+count+' 张待导入表，已确认导入的记录不变');return true}finally{busy=false}}
function commitSheet(){try{const sheet=pendingImports[0];if(sheet.type==='groups'){const invalid=[];sheet.rows.slice(sheet.header+1).forEach((row,i)=>{const raw=V.normalize(row[sheet.map.cap]),name=V.normalize(row[sheet.map.groupName]);if(raw&&!/合计|总计|小计/.test(name)&&(!Number.isInteger(Number(raw))||Number(raw)<1))invalid.push({row:i+sheet.header+1,raw,name})});if(invalid.length){modal('确认不明确的名额',`<p>以下名额不是单个正整数，请填写实际人数。不会修改原文件。</p><form id="capacityFix">${invalid.map(r=>`<label class="field">第${r.row+1}行 · ${esc(r.name)} · 原值 ${esc(r.raw)}<input type="number" min="1" step="1" required data-row="${r.row}" placeholder="实际名额"></label>`).join('')}<div class="form-actions"><button class="primary">确认并预览</button></div></form>`);$('capacityFix').onsubmit=e=>{e.preventDefault();for(const input of e.target.querySelectorAll('[data-row]')){const n=Number(input.value);if(!Number.isInteger(n)||n<1)return toast('请填写正整数');sheet.rows[Number(input.dataset.row)][sheet.map.cap]=String(n)}closeModal();commitSheet()};return}}
 const records=parseSheet(sheet);if(!records.length)throw Error('没有识别到有效记录，请检查表头行');if(sheet.type==='groups')return editGroupImportPreview(sheet,records);if(sheet.editingSourceId)return reviewImportEdit(sheet,records);commitParsed(sheet,records)}catch(e){errorBox(e)}}
function prepareGroupImport(sheet,records,values){
 const draft=V.copy(sheet),edited=records.map((g,i)=>{const value=values[i];if(!value)throw Error('小组记录不完整，请重新预览');const no=V.normalize(value.no),name=V.normalize(value.name),cap=Number(value.cap),region=V.normalize(value.region);if(!no||!name)throw Error('第 '+(i+1)+' 项的组号和名称不能为空');if(!Number.isInteger(cap)||cap<1)throw Error('第 '+(i+1)+' 项名额须为正整数');return {...g,no,name,cap,region}});
 // Persist the confirmed values in the import draft too, so reopening never resurrects the old data.
 const fields={no:'组号',groupName:'小组名称',cap:'总名额',region:'所属区域'};
 for(const [key,label] of Object.entries(fields)){if(!(draft.map[key]>=0)){draft.map[key]=draft.rows[draft.header].length;draft.rows[draft.header].push(label)}}
 if(new Set(Object.keys(fields).map(k=>draft.map[k])).size!==4)throw Error('组号、名称、名额和区域不能使用同一列，请返回检查列对应关系');
 const mapped=new Set(Object.keys(fields).map(k=>draft.map[k]));draft.merges=(draft.merges||[]).filter(m=>![...mapped].some(c=>c>=m.s.c&&c<=m.e.c));
 edited.forEach(g=>{const row=g.importRow-1;if(!Number.isInteger(row)||row<=draft.header)throw Error('无法定位原始行，请重新预览');draft.rows[row]??=[];for(const [key,value] of Object.entries({no:g.no,groupName:g.name,cap:String(g.cap),region:g.region}))draft.rows[row][draft.map[key]]=value});
 return {sheet:draft,records:edited};
}
let groupPreviewDraft=null;
function groupPreviewRow(g,i){return `<tr data-group-import="${i}"><td><input data-field="no" aria-label="组号" value="${esc(g.no)}" required></td><td><input data-field="name" aria-label="子岗位名称" value="${esc(g.name)}" required></td><td><input data-field="cap" aria-label="名额" type="number" min="1" step="1" value="${g.cap}" required oninput="updateGroupImportTotal()"></td><td><input data-field="region" aria-label="区域" value="${esc(g.region)}"></td><td><button type="button" class="delete-group-button" onclick="deletePreviewGroup(this,${i})">删除</button></td></tr>`}
function addPreviewGroup(){const d=groupPreviewDraft,i=d.records.length;d.sheet.rows.push([]);const g={id:V.uid(),no:String(i+1),name:'',cap:1,region:'',leader:null,area:null,importRow:d.sheet.rows.length};d.records.push(g);$('groupImportRows').insertAdjacentHTML('beforeend',groupPreviewRow(g,i));updateGroupImportTotal();$('groupImportRows').lastElementChild.querySelector('[data-field="name"]').focus()}
function deletePreviewGroup(button,i){const d=groupPreviewDraft;d.sheet.excludedRows??=[];d.sheet.excludedRows.push(d.records[i].importRow);button.closest('tr').remove();updateGroupImportTotal()}
function editGroupImportPreview(sheet,records){
 groupPreviewDraft={sheet:V.copy(sheet),records:V.copy(records)};
 modal('确认小组与名额',`<form id="groupImportForm"><p class="subtext">相同组号下，每行是独立子岗位，共用组长。确认后生效。</p><button type="button" onclick="addPreviewGroup()">＋ 添加子岗位</button><div class="tablewrap group-import-editor"><table><thead><tr><th>组号</th><th>子岗位名称</th><th>总名额</th><th>区域</th><th>操作</th></tr></thead><tbody id="groupImportRows">${records.map(groupPreviewRow).join('')}</tbody></table></div><div class="form-actions"><span class="subtext" id="groupImportTotal"></span><span class="spacer"></span><button type="button" onclick="closeModal()">返回</button><button type="submit" class="primary" id="acceptGroups">${sheet.editingSourceId?'预览修改':'确认导入'}</button></div></form>`);updateGroupImportTotal();
 $('groupImportForm').onsubmit=e=>{e.preventDefault();if(busy)return;try{const rows=[...e.target.querySelectorAll('[data-group-import]')];if(!rows.length)throw Error('请至少保留一个子岗位');const values=rows.map(row=>Object.fromEntries([...row.querySelectorAll('[data-field]')].map(input=>[input.dataset.field,input.value]))),selectedRecords=rows.map(row=>groupPreviewDraft.records[Number(row.dataset.groupImport)]);const result=prepareGroupImport(groupPreviewDraft.sheet,selectedRecords,values);if(sheet.editingSourceId)reviewImportEdit(result.sheet,result.records);else commitParsed(result.sheet,result.records)}catch(error){toast(error.message)}};
}
function updateGroupImportTotal(){const inputs=[...$('groupImportForm').querySelectorAll('[data-field="cap"]')],valid=inputs.every(input=>Number.isInteger(Number(input.value))&&Number(input.value)>0);$('groupImportTotal').textContent=valid?inputs.length+' 个项目 · 共 '+inputs.reduce((n,input)=>n+Number(input.value),0)+' 人':'名额须为正整数'}
function templateRows(sample){const out={小组信息:[['组号','小组名称','总名额','所属区域']],内部人员:[['学号','姓名','报名意向','邮箱','摄影标志','小闪电标志']],团体人员:[['学号','姓名','团体名称','邮箱','摄影标志','小闪电标志']],情侣人员:[['学号','姓名','关联志愿者姓名','配对编号','邮箱','摄影标志','小闪电标志']],家属人员:[['学号','姓名','关联志愿者姓名','邮箱','摄影标志','小闪电标志']],普通人员:[['学号','姓名','邮箱','摄影标志','小闪电标志']]};if(sample){out.小组信息.push(['1','起点服务',8,'起点'],['2','赛道补给',8,'赛道'],['3','终点引导',8,'终点']);for(let i=1;i<=9;i++)out.内部人员.push(['I'+String(i).padStart(3,'0'),['林晓','陈宇','张宁','周悦','何安','顾言','许晨','赵晴','李桐'][i-1],i<=3?'小组长':i===4?'区长':'不报名','',i===5?'是':'否',i===6?'是':'否']);out.团体人员.push(['T001','王晨','学生会','','否','是'],['T002','刘月','学生会','','是','否'],['T003','杨帆','青协','','否','否'],['T004','吴佳','青协','','否','是']);out.情侣人员.push(['C001','陆星','江月','','','是','否'],['C002','江月','陆星','','','否','否']);out.家属人员.push(['','陈夏','陈宇','','否','否']);out.普通人员.push(['I001','林晓','','是','否']);for(let i=1;i<=15;i++)out.普通人员.push(['N'+String(i).padStart(3,'0'),'普通志愿者'+i,'',i%6===0?'是':'否',i%5===0?'是':'否'])}return out}
function downloadTemplates(sample){const wb=XLSX.utils.book_new();Object.entries(templateRows(sample)).forEach(([name,rows])=>{const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=rows[0].map(()=>({wch:22}));XLSX.utils.book_append_sheet(wb,ws,name)});download(sample?'志愿者测试样例.xlsx':'志愿者导入模板.xlsx',XLSX.write(wb,{bookType:'xlsx',type:'array'}));toast(sample?'样例包含跨表重复记录，可测试完整流程':'模板已下载')}
function recommendedRecord(rows){const specialized=rows.filter(p=>['team','couple'].includes(p.cat));return rows.some(p=>p.cat==='normal')&&specialized.length?specialized[0].id:rows[0]?.id}
function renderDedup(){const sets=V.duplicateSets(S),set=sets[0];const recommended=set?recommendedRecord(set):null;V.resolveFamily(S);const errors=V.relationErrors(S);issuePeople=V.issueIds(S);$('mainContent').innerHTML=`<div class="section-card"><div class="section-top"><h2>重复记录</h2><span class="badge">${sets.length} 组待处理</span></div>${set?`<p class="subtext">已优先选择团体／情侣记录（相较普通记录），请确认保留来源。</p><div class="dedup-grid">${set.map((p,i)=>`<label class="duplicate"><input type="radio" name="keep" value="${p.id}" ${p.id===recommended?'checked':''}><strong>${esc(p.name)}</strong>${p.id===recommended?'<span class="badge">建议保留</span>':''}<div>${esc(p.student||'无学号')} · ${V.CATS[p.cat]}</div><div class="subtext">${p.origins.map(o=>esc(o.file+' / '+o.sheet+' 第'+o.row+'行')).join('<br>')}</div><div class="subtext">${esc(p.email)} ${p.photo?'📷':''} ${p.run?'🏃':''}</div><details><summary>完整字段</summary><pre>${esc(JSON.stringify(p.raw,null,2))}</pre></details></label>`).join('')}</div><label class="subtext"><input id="keepRelations" type="checkbox" checked> 保留各记录的绑定关系与摄影 / 小闪电标签</label><div class="form-actions"><button onclick="distinctCurrent()">确认为不同的人</button><button class="primary" onclick="mergeCurrent()">保留所选记录</button></div>`:'<div class="empty">✓ 无待处理重复记录</div>'}</div><div class="section-card"><div class="section-top"><h2>绑定关系</h2><button onclick="openRoster()">查看 / 编辑全部人员</button></div>${errors.length?`<div class="notice">${errors.slice(0,12).map(esc).join('<br>')}${errors.length>12?'<br>另有 '+(errors.length-12)+' 项':''}</div>`:'<p class="subtext">✓ 绑定关系检查通过</p>'}${S.people.filter(p=>p.familyName||p.partnerName||p.cat==='family'||p.cat==='couple'||issuePeople.has(p.id)).map(p=>`<div class="histrow"><span class="${issuePeople.has(p.id)?'issue-text':''}">${esc(p.name)} → ${esc(personOf(p.partnerTarget)?.name||p.partnerName||personOf(p.familyTarget)?.name||p.familyName||S.people.find(x=>x.partnerTarget===p.id)?.name||p.pairs.join('、')||'未设置')}</span><button onclick="editPerson('${p.id}')">修改关联</button></div>`).join('')}</div>`}
function distinctCurrent(){const set=V.duplicateSets(S)[0];mutate(()=>V.markDistinct(S,set.map(p=>p.id)));toast('已标记为不同的人')}
function mergeCurrent(){const keep=document.querySelector('[name=keep]:checked')?.value,rels=$('keepRelations').checked,ids=V.duplicateSets(S)[0].map(p=>p.id);if(!keep)return;if(mutate(()=>{V.merge(S,ids,keep,rels);V.resolveFamily(S)}))toast('已保留所选来源')}
function openRoster(){modal('全部人员',`<input class="wide" placeholder="搜索姓名 / 学号" oninput="filterRoster(this.value)"><div id="rosterList">${rosterRows('')}</div>`)}
function rosterRows(q){return S.people.filter(p=>!q||p.name.includes(q)||p.student.includes(q)).map(p=>`<div class="histrow"><div><span class="${issuePeople.has(p.id)?'issue-text':''}">${esc(p.name)}</span> <span class="badge">${V.CATS[p.cat]}</span><br><span class="subtext">${esc(p.student)} ${p.photo?'📷':''}${p.run?'🏃':''}</span></div><button onclick="editPerson('${p.id}')">编辑</button></div>`).join('')}
function filterRoster(q){$('rosterList').innerHTML=rosterRows(q)}
function withdrawDialog(id){const p=personOf(id);modal('放弃参加 · '+p.name,`<p>移出分配名单，保留原始信息与退出原因。关联同伴将保留并提示检查。</p><label>原因（可选）<input id="withdrawReason" class="wide" placeholder="可留空"></label><div class="form-actions"><button onclick="editPerson('${id}')">返回</button><button class="delete-group-button" onclick="applyWithdrawal('${id}')">确认放弃参加</button></div>`)}
async function applyWithdrawal(id){const reason=$('withdrawReason').value;if(!await saveSnapshot('人员放弃参加前'))return;if(mutate(()=>V.withdraw(S,id,reason),true)){selected.delete(id);closeModal();await saveSnapshot('人员放弃参加');toast('已移入放弃参加名单')}}
function showWithdrawn(){modal('放弃参加',`<div>${(S.withdrawn||[]).map(p=>`<div class="histrow"><div><b>${esc(p.name)}</b> · ${esc(p.student)}<p>${esc(p.withdrawalReason||'未注明原因')}</p><small>${esc(p.withdrawnAt||'')}</small></div><button onclick="restoreParticipant('${p.id}')">恢复参加</button></div>`).join('')||'<div class="empty">暂无记录</div>'}</div>`)}
function restoreParticipant(id){if(mutate(()=>V.restoreWithdrawn(S,id),true)){showWithdrawn();saveSnapshot('恢复参加');toast('已恢复至待分配，请重新确认关系')}}
function editPerson(id){const p=personOf(id);modal('编辑人员',`<form id="personForm"><div class="formrow"><label>姓名<input name="name" value="${esc(p.name)}" required></label><label>学号<input name="student" value="${esc(p.student)}"></label><label>邮箱<input name="email" value="${esc(p.email)}"></label><label>人员类别<select name="cat">${Object.entries(V.CATS).map(([k,v])=>`<option value="${k}" ${p.cat===k?'selected':''}>${v}</option>`).join('')}</select></label><label>是否小组长<select name="intent">${['不报名','小组长','区长','两者均报名'].map(k=>`<option ${p.intent===k?'selected':''}>${k}</option>`).join('')}</select></label><label>团体（多个用逗号）<input name="teams" value="${esc(p.teams.join('，'))}"></label><label>配对编号（可选）<input name="pairs" value="${esc(p.pairs.join('，'))}"></label><label>情侣关联姓名<select name="partnerTarget"><option value="">无关联 / 使用配对编号</option>${!p.partnerTarget&&p.partnerName?`<option value="__unresolved" selected>待确认：${esc(p.partnerName)}</option>`:''}${S.people.filter(x=>x.id!==id).map(x=>`<option value="${x.id}" ${p.partnerTarget===x.id?'selected':''}>${esc(x.name+' · '+(x.student||V.CATS[x.cat]))}</option>`).join('')}</select></label><label>家属关联姓名<select name="familyTarget"><option value="">无关联</option>${!p.familyTarget&&p.familyName?`<option value="__unresolved" selected>待确认：${esc(p.familyName)}</option>`:''}${S.people.filter(x=>x.id!==id).map(x=>`<option value="${x.id}" ${p.familyTarget===x.id?'selected':''}>${esc(x.name+' · '+(x.student||V.CATS[x.cat]))}</option>`).join('')}</select></label></div><div class="columns"><label><input name="photo" type="checkbox" ${p.photo?'checked':''}> 📷 摄影</label><label><input name="run" type="checkbox" ${p.run?'checked':''}> 🏃 小闪电</label></div>${personInfo(p,true)}<p class="subtext">修改身份或关系后，需重新查重及确认分配。已有位置保留。</p><div class="form-actions"><button type="button" class="delete-group-button" onclick="withdrawDialog('${id}')">放弃参加</button><button type="button" onclick="closeModal()">取消</button><button class="primary">保存</button></div></form>`);$('personForm').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target);if(!V.normalize(form.get('name')))return toast('姓名不能为空');if(S.confirmed.roles&&!await saveSnapshot('编辑人员前备份'))return;const split=x=>String(x||'').split(/[,，]/).map(V.normalize).filter(Boolean);mutate(()=>{const p=personOf(id);if(form.get('cat')!==p.cat)p.autoCoupleFrom='';Object.assign(p,{name:V.normalize(form.get('name')),student:V.normalize(form.get('student')),email:V.normalize(form.get('email')),cat:form.get('cat'),intent:form.get('intent'),teams:split(form.get('teams')),pairs:split(form.get('pairs')),photo:form.has('photo'),run:form.has('run'),partnerTarget:form.get('partnerTarget')==='__unresolved'?null:form.get('partnerTarget')||null,partnerName:form.get('partnerTarget')==='__unresolved'?p.partnerName:personOf(form.get('partnerTarget'))?.name||'',familyTarget:form.get('familyTarget')==='__unresolved'?null:form.get('familyTarget')||null,familyName:form.get('familyTarget')==='__unresolved'?p.familyName:personOf(form.get('familyTarget'))?.name||''});V.resolveFamily(S);},true);closeModal()}}
let allCandidates=false;
function renderRoles(){const internals=S.people.filter(p=>p.cat==='internal'&&!p.deferred);$('mainContent').innerHTML=`<div class="section-card"><div class="section-top"><h2>小组与任职</h2><div><label class="subtext"><input type="checkbox" ${allCandidates?'checked':''} onchange="allCandidates=this.checked;renderRoles()"> 全部内部人员</label> <button onclick="undo()" ${undoStack.length?'':'disabled'}>↶ 撤销</button> <button class="primary" id="autoLeaders" onclick="autoAssignLeaders()">自动分配组长</button> <button onclick="editGroup()">＋ 添加小组</button></div></div><p class="subtext">同组共用组长，仅计一人。自动分配保留已有选择，优先报名人选；勾选“全部内部人员”可补选其他人。</p>${S.people.some(p=>p.group)?'<p class="subtext">重新确认任职会重建组长位置，后续人员需重新分配；旧快照保留。</p>':''}<div class="tablewrap"><table><thead><tr><th>小组</th><th>名额</th><th>小组长</th><th>区长（可选）</th><th></th></tr></thead><tbody>${S.groups.map(g=>`<tr><td><b>${esc(g.no+'组 · '+g.name)}</b><br><span class="subtext">${esc(g.region)}</span></td><td>${g.cap}</td><td><select aria-label="${esc(g.no)}组 ${esc(g.name)} 小组长" onchange="setRole('${g.id}','leader',this.value)"><option value="">选择组长</option>${internals.filter(p=>allCandidates||/小组长|两者/.test(p.intent)||p.id===g.leader).map(p=>`<option value="${p.id}" ${p.id===g.leader?'selected':''}>${esc(p.name)}${S.groups.some(x=>x.leader===p.id&&V.normalize(x.no)!==V.normalize(g.no))?'（其他组已任职）':S.groups.some(x=>x.leader===p.id&&x.id!==g.id)?'（同组共用）':''}</option>`).join('')}</select></td><td><select aria-label="${esc(g.no)}组区长" onchange="setRole('${g.id}','area',this.value)"><option value="">不设置</option>${internals.filter(p=>allCandidates||/区长|两者/.test(p.intent)||p.id===g.area).map(p=>`<option value="${p.id}" ${p.id===g.area?'selected':''}>${esc(p.name)}</option>`).join('')}</select></td><td><button onclick="editGroup('${g.id}')">编辑</button> <button class="delete-group-button" onclick="requestDeleteGroup('${g.id}')">删除</button></td></tr>`).join('')}</tbody></table></div></div><div class="section-card"><h2>区长编组</h2>${internals.filter(p=>S.groups.some(g=>g.area===p.id)).map(p=>`<div class="histrow"><span>${esc(p.name)} <span class="subtext">${S.groups.filter(g=>g.area===p.id).map(g=>esc(g.no)+'组').join('、')}</span></span><select onchange="setIndependent('${p.id}',this.value==='yes')"><option value="no" ${!p.independent?'selected':''}>编入小组（可兼任）</option><option value="yes" ${p.independent?'selected':''}>独立管理，不占名额</option></select></div>`).join('')||'<p class="subtext">未设置区长</p>'}</div>`}
async function autoAssignLeaders(){if(busy)return;try{const plan=V.assignLeaders(S,allCandidates);if(!plan.changed){if(plan.missing.length)return errorBox(Error('仍有 '+plan.missing.length+' 组未设置：'+plan.missing.join('、')+'。可用人选不足，或绑定人数超过项目容量。'+(allCandidates?'请调整名单或容量。':'可勾选“全部内部人员”扩大候选范围。')));return toast('所有小组已有组长，已保留现有选择')}if(S.confirmed.roles||S.people.some(p=>p.group)){busy=true;const saved=await saveSnapshot('自动分配组长前备份');busy=false;if(!saved)return}if(!mutate(()=>{S.groups=plan.groups;invalidateAfterRoles()}))return;toast('已分配 '+plan.assigned+' 位组长，保留 '+plan.retained+' 组原选择');if(plan.missing.length)modal('部分小组待选',`<p>已完成 ${plan.assigned} 组，保留 ${plan.retained} 组。仍缺 ${plan.missing.length} 组：${esc(plan.missing.join('、'))}。</p><p class="subtext">可用人选不足或绑定人数超过项目容量。${allCandidates?'请手动调整名单或名额。':'可勾选“全部内部人员”后再次分配，优先使用报名小组长的人选。'}</p><button onclick="closeModal()">继续调整</button>`)}catch(e){errorBox(e)}finally{busy=false}}
function invalidateAfterRoles(){['roles','internal','team','couple','normal','overview'].forEach(k=>delete S.confirmed[k]);S.teamDone=[];}
function setRole(gid,key,value){mutate(()=>{const target=groupOf(gid);if(key==='leader'){if(value&&S.groups.some(g=>V.normalize(g.no)!==V.normalize(target.no)&&g.leader===value))throw Error('该人员已担任其他组号的组长');S.groups.filter(g=>V.normalize(g.no)===V.normalize(target.no)).forEach(g=>g.leader=value||null)}else target[key]=value||null;invalidateAfterRoles();S.people.forEach(p=>{p.area=S.groups.some(g=>g.area===p.id);if(!p.area)p.independent=false})})}
function setIndependent(id,v){mutate(()=>{personOf(id).independent=v;invalidateAfterRoles()})}
function requestDeleteGroup(id){if(busy)return;try{const plan=V.deleteGroup(S,id);modal('删除小组项目',`<p>删除 ${esc(plan.group.no+'组 · '+plan.group.name)}？</p><div class="notice">${plan.returned} 位人员及绑定成员退回待分配，人员名单保留。${plan.releasedArea?'另有 '+plan.releasedArea+' 位不再任职的独立区长回到待分配。':''}${plan.siblings?'同组号的另外 '+plan.siblings+' 个项目保留。':''}</div><p class="subtext">任职及后续阶段需重新确认。删除前后保存历史，也可以点击“撤销”恢复。</p><div class="form-actions"><button onclick="closeModal()">取消</button><button id="deleteGroupConfirm" class="primary" onclick="applyDeleteGroup('${id}')">确认删除</button></div>`)}catch(e){errorBox(e)}}
async function applyDeleteGroup(id){if(busy)return false;busy=true;const button=$('deleteGroupConfirm');if(button)button.disabled=true;try{const plan=V.deleteGroup(S,id);if(!await saveSnapshot('删除小组前 · '+plan.group.name))return false;if(!await saveSnapshot('删除小组 · '+plan.group.name,plan.state))return false;checkpoint();S=plan.state;recoverExport();selected.clear();focusId=null;page='roles';closeModal();render();toast('已删除项目，可撤销或从历史恢复');return true}catch(e){errorBox(e);return false}finally{busy=false;render();if(button)button.disabled=false}}
function editGroup(id){const g=groupOf(id)||{no:String(nextGroupNumber()),name:'',cap:30,region:''};modal(id?'编辑小组':'添加小组',`<form id="groupForm"><div class="formrow"><label>组号<input name="no" value="${esc(g.no)}" required></label><label>项目名称<input name="name" value="${esc(g.name)}" required></label><label>名额（含组长）<input type="number" name="cap" value="${g.cap}" min="1" step="1" required></label><label>区域<input name="region" value="${esc(g.region)}"></label></div><div class="form-actions"><button class="primary">保存</button></div></form>`);$('groupForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),no=V.normalize(f.get('no')),cap=Number(f.get('cap'));if(!Number.isInteger(cap)||cap<1)return toast('名额须为正整数');if(id&&S.people.filter(p=>p.group===id).length>cap)return toast('新名额小于当前人数，请先调整人员');mutate(()=>{const data={no,name:V.normalize(f.get('name')),cap,region:V.normalize(f.get('region'))};if(id)Object.assign(groupOf(id),data);else S.groups.push({id:V.uid(),leader:null,area:null,...data});invalidateAfterRoles()});closeModal()}}
const baseColumns=[['name','姓名'],['student','学号'],['group','小组'],['leader','小组长'],['area','区长'],['role','角色'],['cat','来源类别'],['source','来源表单'],['team','团体'],['photo','摄影'],['run','小闪电'],['email','邮箱']];
function availableColumns(){const raw=[...new Set(S.people.flatMap(p=>Object.keys(p.raw)))];const custom=[...new Set(S.people.flatMap(p=>Object.keys(extraValues(p))))];return [...baseColumns,...custom.map(k=>['custom:'+k,k]),...raw.map(k=>['raw:'+k,'原始 · '+k])]}
function columnValue(p,key){const g=groupOf(p.group);if(key.startsWith('custom:'))return extraValues(p)[key.slice(7)]||'';if(key.startsWith('raw:'))return p.raw[key.slice(4)]||'';return ({name:p.name,student:p.student,email:p.email,group:g?g.no+'组 · '+g.name:p.reserve?'储备':p.independent?'独立区长':'待分配',leader:personOf(g?.leader)?.name||'',area:personOf(g?.area)?.name||'',role:[leader(p)?'小组长':'',p.area?'区长':''].filter(Boolean).join(' / ')||'组员',cat:V.CATS[p.cat],source:p.origins.map(o=>o.file+'/'+o.sheet).join('；'),team:p.teams.join('、'),photo:p.photo?'是':'否',run:p.run?'是':'否'})[key]??''}
function exportColumnLabel(key){const custom=S.exportColumnNames;if(custom&&Object.prototype.hasOwnProperty.call(custom,key)&&typeof custom[key]==='string'&&custom[key].trim())return custom[key].trim();return availableColumns().find(c=>c[0]===key)?.[1]||key}
function setExportColumnName(key,value){const name=V.normalize(value);if(!name)throw Error('列名称不能为空');if(name.length>100)throw Error('列名称最多100字');S.exportColumnNames={...(S.exportColumnNames||{}),[key]:name}}
function editExportColumnName(index){const key=exportCols[index];if(!key)return;const original=availableColumns().find(c=>c[0]===key)?.[1]||key;modal('修改导出列名',`<form id="exportNameForm"><p class="subtext">原字段：${esc(original)}。仅修改导出名称，数据保持不变。</p><label>列名称<input id="exportNameInput" class="wide" maxlength="100" required value="${esc(exportColumnLabel(key))}"></label><div class="form-actions"><button type="button" id="resetExportName">恢复默认</button><button type="button" onclick="closeModal()">取消</button><button class="primary" type="submit">保存</button></div></form>`);$('resetExportName').onclick=()=>{$('exportNameInput').value=original};$('exportNameForm').onsubmit=e=>{e.preventDefault();try{const name=$('exportNameInput').value;if(!V.normalize(name))return toast('列名称不能为空');checkpoint();setExportColumnName(key,name);changed();closeModal();renderExport();toast('已更新列名')}catch(error){toast(error.message)}};$('exportNameInput').focus();$('exportNameInput').select()}
function openExport(id){exportInitialized=true;exportSelection=id?[id]:S.groups.map(g=>g.id);if(!exportCols.length)exportCols=['name','student','group','role','photo','run'];page='export';render()}
function renderExport(){
 const root=$('mainContent'),existing=root.querySelector('.export-grid');
 if(!existing)return renderExportContent();
 const positions=[...existing.querySelectorAll('.checklist,.tablewrap')].map(el=>({top:el.scrollTop,left:el.scrollLeft}));
 const ancestors=[];for(let el=root;el;el=el.parentElement)ancestors.push({el,top:el.scrollTop,left:el.scrollLeft});
 const active=document.activeElement,field=active?.dataset?.col,group=active?.dataset?.exportGroup,special=active?.id==='exportReserveChoice';
 renderExportContent();
 const lists=root.querySelectorAll('.checklist,.tablewrap');positions.forEach((pos,i)=>{if(lists[i]){lists[i].scrollTop=pos.top;lists[i].scrollLeft=pos.left}});
 const target=field?[...root.querySelectorAll('[data-col]')].find(el=>el.dataset.col===field):group?[...root.querySelectorAll('[data-export-group]')].find(el=>el.dataset.exportGroup===group):special?$('exportReserveChoice'):null;
 target?.focus({preventScroll:true});ancestors.forEach(({el,top,left})=>{el.scrollTop=top;el.scrollLeft=left});
}
function renderExportContent(){if(!exportInitialized){if(!exportCols.length)exportCols=['name','student','group','role','photo','run'];exportSelection=S.groups.map(g=>g.id);exportInitialized=true;}const cols=availableColumns(),preview=S.people.filter(p=>exportSelection.includes(p.group)||(exportSpecial&&p.reserve));$('mainContent').innerHTML=`<div class="export-grid"><div class="section-card"><div class="section-top"><h2>选择小组</h2><button onclick="toggleAllExportGroups()">${S.groups.length&&S.groups.every(g=>exportSelection.includes(g.id))?'取消全选':'全选'}</button></div><div class="checklist">${S.groups.map(g=>`<label><input type="checkbox" ${exportSelection.includes(g.id)?'checked':''} data-export-group="${g.id}" onchange="toggleExportGroup('${g.id}',this.checked)">${esc(g.no+'组 · '+g.name)} <span class="subtext">${S.people.filter(p=>p.group===g.id).length} 人</span></label>`).join('')}<label><input id="exportReserveChoice" type="checkbox" ${exportSpecial?'checked':''} onchange="exportSpecial=this.checked?'reserve':'';rememberExport();renderExport()">储备名单</label></div><div class="section-top" style="margin-top:25px"><h2>导出字段</h2><button onclick="toggleAllExportColumns()">${cols.length&&cols.every(([k])=>exportCols.includes(k))?'取消全选':'全选'}</button></div><div class="checklist">${cols.map(([k,label])=>`<label><input type="checkbox" ${exportCols.includes(k)?'checked':''} data-col="${esc(k)}" onchange="toggleColumn(this.dataset.col,this.checked)">${esc(label)}</label>`).join('')}</div></div><div><div class="section-card"><div class="section-top"><h2>列顺序与预览</h2><span class="badge">${preview.length} 人</span></div><div class="column-order">${exportCols.map((k,i)=>`<span class="export-column-item"><span class="export-column-tag" draggable="true" tabindex="0" role="button" aria-label="${esc(exportColumnLabel(k))}，拖拽排序，左右方向键移动" data-column-index="${i}" ondragstart="startColumnDrag(event,${i})" ondragover="overColumnDrag(event)" ondragleave="this.classList.remove('column-before','column-after')" ondrop="dropColumnDrag(event,${i})" ondragend="endColumnDrag()" onkeydown="if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();shiftColumn(${i},event.key==='ArrowLeft'?-1:1)}"><span aria-hidden="true" class="column-grip">⠿</span>${esc(exportColumnLabel(k))}</span><button class="rename-column" type="button" title="修改列名" aria-label="修改${esc(exportColumnLabel(k))}的导出名称" onclick="editExportColumnName(${i})">✎</button></span>`).join('')}</div><div class="tablewrap export-full-preview" tabindex="0" aria-label="全部已选人员预览"><table><thead><tr>${exportCols.map(k=>`<th>${esc(exportColumnLabel(k))}</th>`).join('')}</tr></thead><tbody>${preview.map(p=>`<tr>${exportCols.map(k=>`<td>${esc(columnValue(p,k))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="subtext">全部 ${preview.length} 人 · 可上下及左右滚动 · 修改名单后请重新导出</p><div class="form-actions"><select id="exportMode" onchange="exportMode=this.value;rememberExport()"><option value="book" ${exportMode==='book'?'selected':''}>一个文件，多张工作表</option><option value="zip" ${exportMode==='zip'?'selected':''}>每组一个文件，打包下载</option></select><button class="primary" onclick="exportExcel()">导出 Excel</button></div></div><div class="section-card"><h2>组长邮件草稿</h2><p class="subtext">每位组长只附本组名单，使用上方选定列。下载后通过邮箱客户端发送。</p><div id="mailRecipients">${S.groups.filter(g=>exportSelection.includes(g.id)).map(g=>`<div class="formrow"><label>${esc(g.no+'组 · '+(personOf(g.leader)?.name||'未设组长'))}<input data-mail-group="${g.id}" type="email" value="${esc(S.mailDraft?.recipients?.[g.id]??personOf(g.leader)?.email??'')}" oninput="rememberMail()" placeholder="组长邮箱"></label></div>`).join('')}</div><label class="field">主题<input id="mailSubject" class="wide" maxlength="150" oninput="rememberMail()" value="${esc(S.mailDraft?.subject??(S.name+' · {小组}名单'))}"></label><label class="field">正文<textarea id="mailBody" class="wide" rows="4" oninput="rememberMail()">${esc(S.mailDraft?.body??('{组长}，你好：\n附件为{小组}的志愿者名单，请查收。\n\n'+S.name))}</textarea></label><div class="form-actions"><button onclick="previewMail()">预览邮件</button><button class="primary" onclick="exportMail()">生成草稿</button></div></div></div></div>`}
function rememberMail(){const recipients={...(S.mailDraft?.recipients||{})};document.querySelectorAll('[data-mail-group]').forEach(el=>recipients[el.dataset.mailGroup]=el.value);S.mailDraft={subject:$('mailSubject').value,body:$('mailBody').value,recipients};changed()}
function rememberExport(){S.exportPrefs={cols:[...exportCols],groups:[...exportSelection],mode:exportMode,special:exportSpecial};changed()}
function recoverExport(){const pref=S.exportPrefs;if(pref){exportCols=Array.isArray(pref.cols)?pref.cols:[];exportSelection=Array.isArray(pref.groups)?pref.groups.filter(id=>groupOf(id)):[];exportMode=pref.mode==='zip'?'zip':'book';exportSpecial=pref.special?'reserve':'';exportInitialized=true}else{exportCols=[];exportSelection=[];exportMode='book';exportSpecial='';exportInitialized=false}}
function toggleAllExportGroups(){const all=S.groups.length&&S.groups.every(g=>exportSelection.includes(g.id));exportSelection=all?[]:S.groups.map(g=>g.id);rememberExport();renderExport()}
function toggleAllExportColumns(){const keys=availableColumns().map(([key])=>key),all=keys.length&&keys.every(k=>exportCols.includes(k));exportCols=all?[]:[...exportCols.filter(k=>keys.includes(k)),...keys.filter(k=>!exportCols.includes(k))];rememberExport();renderExport()}
function toggleExportGroup(id,on){exportSelection=on?[...new Set([...exportSelection,id])]:exportSelection.filter(x=>x!==id);rememberExport();renderExport()}
function toggleColumn(k,on){exportCols=on?[...new Set([...exportCols,k])]:exportCols.filter(x=>x!==k);rememberExport();renderExport()}
let draggedColumn=null;
function startColumnDrag(event,index){draggedColumn=exportCols[index];event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',draggedColumn);event.currentTarget.classList.add('column-dragging')}
function overColumnDrag(event){if(draggedColumn===null)return;event.preventDefault();event.dataTransfer.dropEffect='move';const el=event.currentTarget,rect=el.getBoundingClientRect();document.querySelectorAll('.export-column-tag').forEach(x=>x.classList.remove('column-before','column-after'));el.classList.add(event.clientX<rect.left+rect.width/2?'column-before':'column-after')}
function endColumnDrag(){draggedColumn=null;document.querySelectorAll('.export-column-tag').forEach(x=>x.classList.remove('column-before','column-after','column-dragging'))}
function reorderedColumns(cols,key,target,after){if(key===target||!cols.includes(key)||!cols.includes(target))return [...cols];const next=cols.filter(k=>k!==key),index=next.indexOf(target)+(after?1:0);next.splice(index,0,key);return next}
function dropColumnDrag(event,index){if(draggedColumn===null)return;event.preventDefault();const rect=event.currentTarget.getBoundingClientRect(),key=draggedColumn;exportCols=reorderedColumns(exportCols,key,exportCols[index],event.clientX>=rect.left+rect.width/2);endColumnDrag();rememberExport();renderExport();document.querySelectorAll('.export-column-tag')[exportCols.indexOf(key)]?.focus({preventScroll:true})}
function shiftColumn(i,d){if(i+d<0||i+d>=exportCols.length)return;[exportCols[i],exportCols[i+d]]=[exportCols[i+d],exportCols[i]];rememberExport();renderExport()}
function outputSheet(g,reserve=false){const cols=availableColumns(),ps=S.people.filter(p=>reserve?p.reserve:p.group===g.id);const header=exportCols.map(k=>exportColumnLabel(k)),rows=[[S.name],[reserve?'储备名单':g.no+'组 · '+g.name],['导出时间：'+now()+' · 项目修订 '+S.revision],...(reserve?[]:[['小组长：'+(personOf(g.leader)?.name||'未设置')+'　区长：'+(personOf(g.area)?.name||'未设置')]]),[],header,...ps.map(p=>exportCols.map(k=>String(columnValue(p,k))))];const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=header.map(()=>({wch:20}));const start=reserve?4:5;ws['!autofilter']={ref:XLSX.utils.encode_range({s:{r:start,c:0},e:{r:rows.length-1,c:Math.max(0,header.length-1)}})};return ws}
function workbookFor(gs,withReserve=false){if(!exportCols.length)throw Error('至少选择一列');const wb=XLSX.utils.book_new();gs.forEach((g,i)=>{let name=(g.no+'组-'+g.name).replace(/[\\/?*\[\]:]/g,'_').slice(0,24)+'-'+(i+1);XLSX.utils.book_append_sheet(wb,outputSheet(g),name)});if(withReserve)XLSX.utils.book_append_sheet(wb,outputSheet(null,true),'储备名单');if(!wb.SheetNames.length)throw Error('请选择小组或储备名单');return new Uint8Array(XLSX.write(wb,{bookType:'xlsx',type:'array'}))}
function exportExcel(){try{const gs=S.groups.filter(g=>exportSelection.includes(g.id));if(exportMode==='book')download(safeName(S.name)+'-分组名单.xlsx',workbookFor(gs,!!exportSpecial));else{const files=gs.map((g,i)=>({name:safeName(g.no+'组-'+g.name)+'-'+(i+1)+'.xlsx',data:workbookFor([g])}));if(exportSpecial)files.push({name:'储备名单.xlsx',data:workbookFor([],true)});if(!files.length)throw Error('请选择小组');download(safeName(S.name)+'-分组名单.zip',zipFiles(files))}toast('Excel 已生成')}catch(e){errorBox(e)}}
function mailData(){const gs=S.groups.filter(g=>exportSelection.includes(g.id));if(!gs.length)throw Error('请选择至少一个小组');if(!exportCols.length)throw Error('请选择导出列');const subject=$('mailSubject').value.replace(/[\r\n]/g,' '),body=$('mailBody').value;return gs.map(g=>{const p=personOf(g.leader);if(!p)throw Error(g.name+' 尚未设置组长');const email=document.querySelector('[data-mail-group="'+g.id+'"]').value.trim();if(!/^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+$/.test(email))throw Error(g.name+'：请填写有效的组长邮箱');const replace=s=>s.replaceAll('{小组}',g.no+'组 · '+g.name).replaceAll('{组长}',p.name);return {g,p,email,subject:replace(subject),body:replace(body)}})}
function previewMail(){try{const mails=mailData();modal('邮件预览',mails.map(m=>`<div class="section-card"><b>${esc(m.g.no+'组 · '+m.g.name)}</b><p>收件人：${esc(m.email)}</p><p>主题：${esc(m.subject)}</p><pre>${esc(m.body)}</pre><span class="badge">附件：本组名单.xlsx · ${exportCols.length} 列</span></div>`).join(''))}catch(e){errorBox(e)}}
const utf8=s=>new TextEncoder().encode(s);
function b64(bytes){let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s)}
const wrap64=s=>s.match(/.{1,76}/g)?.join('\r\n')||'';
function makeEml(m){const boundary='volunteer-'+V.uid(),encoded=s=>'=?UTF-8?B?'+b64(utf8(s))+'?=',filename='group-'+m.g.no.replace(/[^\w-]/g,'_')+'.xlsx';return ['X-Unsent: 1','To: '+m.email,'Subject: '+encoded(m.subject),'MIME-Version: 1.0','Content-Type: multipart/mixed; boundary="'+boundary+'"','','--'+boundary,'Content-Type: text/plain; charset=UTF-8','Content-Transfer-Encoding: base64','',wrap64(b64(utf8(m.body))),'--'+boundary,'Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet; name="'+filename+'"','Content-Disposition: attachment; filename="'+filename+'"','Content-Transfer-Encoding: base64','',wrap64(b64(workbookFor([m.g]))),'--'+boundary+'--',''].join('\r\n')}
function exportMail(){try{const mails=mailData();if(mails.length===1)download(safeName(mails[0].g.no+'组-'+mails[0].p.name)+'.eml',makeEml(mails[0]),'message/rfc822');else download(safeName(S.name)+'-邮件草稿.zip',zipFiles(mails.map((m,i)=>({name:safeName(m.g.no+'组-'+m.p.name)+'-'+(i+1)+'.eml',data:utf8(makeEml(m))}))));toast('草稿已生成，尚未发送；请用邮箱客户端打开')}catch(e){errorBox(e)}}
function crc32(bytes){let crc=0xffffffff;for(const byte of bytes){crc^=byte;for(let k=0;k<8;k++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}return (crc^0xffffffff)>>>0}
function zipFiles(files){const pieces=[],central=[];let offset=0;const u16=(v,o,n)=>v.setUint16(o,n,true),u32=(v,o,n)=>v.setUint32(o,n,true);for(const f of files){const name=utf8(f.name),data=f.data instanceof Uint8Array?f.data:utf8(f.data),crc=crc32(data),head=new Uint8Array(30+name.length),v=new DataView(head.buffer);u32(v,0,0x04034b50);u16(v,4,20);u16(v,6,0x800);u32(v,14,crc);u32(v,18,data.length);u32(v,22,data.length);u16(v,26,name.length);head.set(name,30);pieces.push(head,data);const c=new Uint8Array(46+name.length),cv=new DataView(c.buffer);u32(cv,0,0x02014b50);u16(cv,4,20);u16(cv,6,20);u16(cv,8,0x800);u32(cv,16,crc);u32(cv,20,data.length);u32(cv,24,data.length);u16(cv,28,name.length);u32(cv,42,offset);c.set(name,46);central.push(c);offset+=head.length+data.length}const size=central.reduce((n,x)=>n+x.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);u32(ev,0,0x06054b50);u16(ev,8,files.length);u16(ev,10,files.length);u32(ev,12,size);u32(ev,16,offset);const out=new Uint8Array(offset+size+22);let pos=0;for(const p of [...pieces,...central,end]){out.set(p,pos);pos+=p.length}return out}
function showHistory(){modal('历史版本',history.length?history.map(h=>`<div class="histrow"><div>${esc(h.label)}<br><span class="subtext">${esc(h.time)} · ${h.state.people.filter(p=>p.group).length}人已分配</span></div><button onclick="restoreSnapshot('${h.id}')">恢复</button></div>`).join(''):'<p>确认阶段后会保存完整快照。</p>')}
async function restoreSnapshot(id){const h=history.find(h=>h.id===id);if(!h)return;const next=V.copy(h.state);try{V.validateFile(next);if(!await saveSnapshot('恢复前备份'))return;if(!await saveSnapshot('恢复至 '+h.label,next,h.pendingImports||[]))return;S=next;pendingImports=V.copy(h.pendingImports||[]);recoverExport();page=S.stage||'overview';selected.clear();undoStack=[];redoStack=[];closeModal();render();toast('已恢复，原状态也已备份')}catch(e){errorBox(e)}}
async function restoreProject(file){if(!file)return;try{if(file.size>100*1024*1024)throw Error('备份文件过大');const b=JSON.parse(await file.text());if(b.format!=='volunteer-project'||b.version!==1)throw Error('不是本应用的项目备份');V.validateFile(b.state);if(S.people.length&&!await saveSnapshot('导入备份前保存'))return;const snaps=Array.isArray(b.snapshots)?b.snapshots:[];for(const h of snaps)V.validateFile(h.state);if(db){await new Promise((res,rej)=>{const tx=db.transaction('snapshots','readwrite');snaps.forEach(h=>tx.objectStore('snapshots').put({...h,id:h.id||V.uid()}));tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}if(!await saveSnapshot('导入项目备份',b.state,b.pendingImports||[]))return;S=b.state;pendingImports=V.copy(b.pendingImports||[]);recoverExport();page=S.stage||'import';selected.clear();undoStack=[];redoStack=[];await loadHistory();render();toast('项目已恢复')}catch(e){errorBox(e)}finally{$('restoreFile').value=''}}
async function loadHistory(){if(!db)return;history=await promiseRequest(db.transaction('snapshots').objectStore('snapshots').getAll());history.sort((a,b)=>(b.created||0)-(a.created||0));}
function activityMenu(){modal('活动管理',`<div class="histrow"><div><b>新建活动</b><br><span class="subtext">从空白名单开始，旧活动保留快照</span></div><button onclick="newProject()">新建</button></div><div class="histrow"><div><b>清空当前活动</b><br><span class="subtext">保留活动名称，清空名单、小组与分配</span></div><button onclick="clearProject()">清空</button></div>`)}
function newProject(){resetProjectDialog('new')}
function clearProject(){resetProjectDialog('clear')}
function resetProjectDialog(mode){if(busy)return toast('请等待当前操作完成');const clear=mode==='clear';modal(clear?'清空当前活动':'新建活动',`<form id="resetProjectForm">${clear?`<p>清空“${esc(S.name)}”的名单、小组、任职及分配结果，保留名称。</p>`:'<label class="field">活动名称<input id="resetActivityName" class="wide" value="新活动" maxlength="60" required></label>'}<p class="subtext">先保存完整快照（含待导入表格），之后可从“历史”恢复。</p><div class="form-actions"><button type="button" onclick="closeModal()">取消</button><button type="submit" class="primary" id="resetProjectSubmit">${clear?'确认清空':'创建活动'}</button></div></form>`);$('resetProjectForm').onsubmit=async e=>{e.preventDefault();const name=clear?S.name:$('resetActivityName').value.trim();if(!name)return toast('请输入活动名称');await resetProject(mode,name)}}
async function resetProject(mode,name){if(busy)return false;busy=true;const button=$('resetProjectSubmit');if(button){button.disabled=true;button.textContent='正在保存…'}try{
 const clear=mode==='clear';if(!await saveSnapshot((clear?'清空前备份 · ':'新建前备份 · ')+S.name))return false;
 const next=V.blank();next.name=name;
 if(!await saveSnapshot((clear?'清空活动 · ':'新建活动 · ')+name,next,[]))return false;
 S=next;pendingImports=[];recoverExport();page='import';selected.clear();focusId=null;lastSelected=null;currentTeam='';query='';filter='';pageNo=1;allCandidates=false;undoStack=[];redoStack=[];dirty=false;closeModal();render();toast(clear?'已清空，可在历史中恢复':'新活动已创建，旧活动可在历史中恢复');return true;
 }finally{busy=false;if(button){button.disabled=false;button.textContent=mode==='clear'?'确认清空':'创建活动'}}}
async function boot(){try{pageSize=Number(localStorage.getItem('volunteer-full-page-size')||4);if(![0,1,2,4,6,8].includes(pageSize))pageSize=4}catch(e){}try{db=await openDB();const current=await promiseRequest(db.transaction('meta').objectStore('meta').get('current'));await loadHistory();const last=history.find(h=>h.id===current);if(last){V.validateFile(last.state);S=last.state;pendingImports=V.copy(last.pendingImports||[]);recoverExport();page=S.stage||'import'}}catch(e){toast('本地存储不可用，请使用项目备份保存进度')}render()}
document.addEventListener('keydown',e=>{if(busy||e.target.isContentEditable)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();e.shiftKey?redo():undo()}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
boot();
